        } else {
            // Next item won't fit in this bin's leftover
            // If this bin is the ONLY fitting bin, prefer using it anyway
            // (avoid opening a new bin), unless leftover becomes a sliver.
            if fitting_bins_count == 1 && bin_residual != bin_capacity {
                score -= 60.0;
            }
            score += 5.0;
        }
    }

    // --- New-bin candidate handling ---
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is only attractive when existing bins fit poorly:
        // penalize proportionally to how many bins already fit the item.
        score += 90.0 * fitting_bins_count as f64;
        // Early in the stream, keeping bins tight matters less; late in the
        // stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * (1.0 - progress);
        // If many open bins with large mean residual, avoid opening more
        if mean_residual > item_size as f64 * 2.0 && open_bins_count > 2 {
            score += 50.0;
        }
    } else {
        // Last-chance bonus: this is the only open bin that fits -> reward using it
        if fitting_bins_count == 1 {
            score -= 80.0;
        }
    }

    // --- Fractional capacity coupling ---
    // Reward bins whose residual is a small fraction of capacity (efficient packing)
    let residual_frac = post_residual as f64 / cap;
    score += residual_frac * 25.0; // lower leftover fraction -> lower score

    // Mild preference for bins below mean residual (tighter than average)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Tiny tie-breaker on item size to stabilize ordering
    score += item_size as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fit bonus: reward using most of the bin.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 12.0;

    // Penalize creating a gap that is too small for the next item if it
    // could otherwise have been used for it.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        let wasted_for_next = (next_item_size - post_residual) as f64;
        if wasted_for_next < 20.0 {
            score += wasted_for_next * 1.5;
        }
    }
    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size as u32 {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins when many are open.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate: make it attractive only when existing residuals are large
    // (i.e., current bins are mostly full) or the fit is poor.
    if bin_residual == bin_capacity {
        // Base handicap so a new bin is only chosen when genuinely better.
        score += 30.0;
        // If mean residual across open bins is small, a fresh bin is reasonable.
        score -= (mean_residual / bin_capacity as f64) * 40.0;
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post_residual,
    // this placement chains into a perfect fit — strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            // Next item fits here afterwards: mild reward proportional to tightness.
            let tight = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - tight / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize dead space.
            score += 50.0 + 0.5 * (post_residual as f64 - mean_residual).abs();
        }
    }

    // Relative-to-mean residual coupling: below-average residual = tight bin, reward.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize leaving very small unusable fragments (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 100.0 * progress;
    } else {
        // New-bin candidate: only attractive when open bins are crowded or fit is poor.
        score += 250.0 * progress + 0.5 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space: residuals too small for any future item (min size 1..100 unknown; assume >=10-ish).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if the next item fits into post_residual, reward this placement (pairing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 35.0 * (post_residual as f64 - next_item_size as f64 + 1.0).ln().max(0.0);
        } else if post_residual > 0 && post_residual < next_item_size {
            // Blocked residual relative to the known next item: penalize proportionally.
            score += 12.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // New-bin candidate logic: opening a new bin is attractive only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Baseline score for a fresh bin: its post_residual equals capacity - item_size.
        // Penalize slightly so tight existing fits win, but reward when open bins are fragmented.
        let fragmentation = (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
        score += 8.0;
        score -= 25.0 * fragmentation;
        // Early in stream, opening bins is cheap; late in stream, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If many bins already open and mean residual is high, discourage yet another bin.
        score += 0.15 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // Mild preference for bins below mean residual (use up emptier bins first, keep fuller ones flexible).
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 10.0 * dev;
    }

    // Time horizon: near the end, prioritize perfect fits even more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 25.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post_residual (tight fit), with non-linear sharpening
    let mut score = pr * (1.0 + 1.5 * pr_norm * pr_norm);

    // Smooth polynomial coupling with stream progress:
    // late in the stream, dead space matters more (fewer future items to fill it)
    score += 12.0 * pr_norm * pr_norm * progress * (1.0 + progress);

    // Penalize residuals that no plausible next item could use (dead space)
    let next = next_item_size as f64;
    if next > 0.0 {
        let waste = (pr - next).max(0.0);
        score += 0.4 * waste * (0.5 + progress);
    } else {
        // last item: waste is permanent
        score += 1.2 * pr;
    }

    // Reward using last-chance bins (avoid opening new bins unnecessarily)
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - 0.5 * pr_norm);
    }

    // Mild preference for bins deviating below mean residual (balance pressure),
    // smoothly scaled by number of open bins
    let dev = (mean_residual - bin_residual as f64) / cap;
    score += 3.0 * dev * dev * (open_bins_count as f64).ln().max(1.0);

    // Small nudge toward fuller bins overall
    score -= 2.0 * (1.0 - bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Residuals in "useful" harmonic classes
    // (capable of holding mid-size future items) are rewarded.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Harmonic class via integer division thresholds on post_residual
    let class = post_residual / quarter; // 0..=4
    match class {
        0 => score -= 6.0,                 // near-perfect fit (0..25)
        1 => score -= 1.5,                 // small but potentially dead space
        2 => score -= 3.0,                 // quarter-to-half: decent
        3 => score -= 4.5,                 // half-to-three-quarter: good
        _ => score -= 2.0,                 // mostly empty bin
    }

    // Modulo arithmetic: leftover after removing multiples of common small
    // item sizes (harmonic divisors). Residuals that are multiples of
    // common item granularities are more likely to be filled exactly later.
    let harmonics: [u32; 5] = [10, 20, 25, 50, 100];
    let mut harmonic_bonus = 0.0;
    for h in harmonics.iter() {
        if post_residual >= *h && post_residual % h == 0 {
            harmonic_bonus += 2.0;
        }
    }
    score -= harmonic_bonus;

    // Penalize awkward residuals: just above a common item size but too
    // small for the next item -> likely dead space.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 4.0; // cannot host the lookahead item
        }
        if post_residual >= next_item_size {
            score -= 2.5; // can host lookahead item
            // Perfect lookahead fit is excellent
            if post_residual == next_item_size {
                score -= 5.0;
            }
        }
        // Lookahead modulo class: mid-size lookahead items favor keeping
        // medium residuals alive.
        let nl = next_item_size / 10; // coarse class 0..=10
        if nl >= 3 && nl <= 6 && post_residual >= next_item_size {
            score -= 1.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the current item leaves a very awkward residual in every open bin
    // or few bins are open (early stream / load balancing).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer new bin early on or when open bins are already tight.
        let openness = mean_residual / c;
        score = 0.35 * c + openness * 40.0 - progress * 25.0
              - (open_bins_count as f64) * 1.5;
        // If a perfect-fit open bin exists elsewhere, new bin is worse;
        // emulate by raising new-bin score when item is small enough that
        // many bins likely fit it.
        if item_size <= half {
            score += 6.0;
        }
    }

    // Dead-space penalty: residual too small for the minimum item size.
    if post_residual > 0 && post_residual < 10 {
        score += 7.0;
    }

    // Mild tie-break: prefer tighter (smaller residual) bins overall.
    score += pr * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }
    // Near-perfect match: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize dead space that next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += 0.5 * dead;
    }

    // Reward tight fits relative to mean residual of open bins.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - post_residual as f64 / cap;
    score -= 20.0 * tightness * (mean_residual / cap);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Prefer opening new bins early when stream is long and few bins open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress) * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: favor bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0; // near-perfect fit, dead space is negligible
    }

    // Penalize large dead space, especially if next item cannot use it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.35 * post_residual as f64;
        } else {
            // Reward bins whose leftover can host the lookahead item.
            score -= 8.0 * (1.0 - (next_item_size as f64 - post_residual as f64).abs() / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate handling: an empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Early in the stream, opening bins is cheap/flexible; later, avoid waste.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
        // If many open bins with slack, opening another is less attractive.
        score += 0.4 * open_bins_count as f64;
    }

    // Coupling with global mean residual: if this bin's residual deviates far from
    // the mean, mildly penalize (prefer balanced consolidation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Small time-varying exploration term to break ties adaptively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.01 * ((step_index as f64 * 0.7).sin()) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Core: strongly prefer tight fits, with super-linear penalty on waste.
    let mut score = 2.5 * norm_pr + 4.0 * norm_pr * norm_pr + 3.0 * norm_pr.powi(3);

    // Exact-fit reward via smooth coupling.
    let exactness = 1.0 - (pr / (cap * 0.5)).tanh().abs();
    score -= 6.0 * exactness * exactness;

    // Stream-progress coupling: waste tolerance shrinks over time.
    score *= 1.0 + 1.5 * progress * norm_pr;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0 + 4.0 * progress;
    }

    // New-bin candidate logic: empty bin should only win when residuals are large
    // or few bins fit the item.
    if bin_residual == bin_capacity {
        let open_penalty = (open_bins_count as f64).ln().max(0.0);
        score += 2.0 + 1.5 * open_penalty + 6.0 * (mean_residual / cap - 0.5).tanh();
        if fitting_bins_count <= 2 {
            score -= 2.5;
        }
        // Late in the stream, opening a fresh bin is more acceptable.
        score -= 2.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 1.5 * (1.0 - slack).max(0.0);
    } else if next_item_size > 0 {
        // Dead space that cannot host the next item: penalize smoothly.
        score += 1.0 + 2.0 * progress;
    }

    // Mild penalty for spreading across many bins.
    score += 0.05 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual classes mod 10
    let class = post_residual % 10;
    // Residuals that are "dead space" (too small for smallest item) are heavily penalized
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward residuals in "useful" harmonic classes (multiples of 5 / 10)
    if class == 0 {
        score -= 6.0;
    } else if class == 5 {
        score -= 3.0;
    } else if class >= 8 {
        score += 3.0; // awkward class
    }

    // Lookahead coupling: prefer bins whose post_residual can still host next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
            // bonus if post_residual is a tight harmonic match for next item
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 3.0;
            } else if gap < 10 {
                score -= 1.5;
            }
        } else {
            score += 4.0; // next item won't fit here -> likely dead space
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer tightest fit (score already grows with post_residual)
        score += 1.0;
    }

    // Fraction-of-capacity coupling: bin_residual as fraction of capacity
    let frac = bin_residual as f64 / bin_capacity as f64;
    if frac > 0.9 {
        score -= 4.0; // nearly full bin, good to fill
    } else if frac < 0.3 {
        score += 3.0; // wasting a mostly-empty bin on a small item
    }

    // Mean-residual coupling: if this bin is far from mean, slight normalization
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    // Late in stream: prioritize closing bins (fewer open bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 {
        score += 0.15 * open_bins_count as f64;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else if post_residual as f64 > 0.5 * bin_capacity as f64 && next_item_size as f64 <= post_residual as f64 {
            // opening a fresh bin can be good for large items leaving huge slack elsewhere
            score -= 2.0;
        } else {
            score += 15.0; // prefer existing bins generally
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: heavy reward.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
        if post_residual < 10 {
            score += 150.0; // unusable sliver (items >= 1... but typical min sizes make this dead)
        } else if post_residual < 20 {
            score += 90.0;
        } else if post_residual < 30 {
            score += 40.0;
        } else if post_residual < 50 {
            score -= 10.0; // medium gaps are reusable
        } else {
            score -= 20.0; // large residual keeps flexibility
        }

        // Reward if the leftover gap can still fit the lookahead item (k=2 lookahead).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
        // Penalize if leftover is a near-miss for the next item (dead space trap).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 25.0;
        }
    }

    // Open-bin pressure: prefer reusing existing bins over opening new ones
    // (a new empty bin has bin_residual == bin_capacity, so it gets no reuse bonus).
    if bin_residual < bin_capacity {
        score -= 15.0 + (open_bins_count as f64) * 2.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

