    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward "nice" residuals that pair well
    // with common item sizes (multiples of 5, 10, 20).
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect closure is best
    } else {
        let class_bonus: f64 = match pr {
            0..=9 => 0.0,                 // dead space: heavily penalized below
            _ if pr % 10 == 0 => 30.0,    // decade residuals: highly reusable
            _ if pr % 20 == 0 => 35.0,
            _ if pr % 5 == 0 => 15.0,
            _ => 0.0,
        };
        score -= class_bonus;

        // Dead-space penalty grows super-linearly for tiny unusable residuals.
        if pr < 10 {
            score += (10 - pr) as f64 * 6.0;
        }
    }

    // Fraction-of-capacity thresholds on post_residual (harmonic fractions).
    let frac = post_residual as f64 / cap;
    if frac > 0.5 {
        score -= 10.0; // still over half-full after placement: good bin
    } else if frac < 0.1 && pr > 0 {
        score += 8.0;  // nearly-closed but not closed: awkward sliver
    }

    // Lookahead coupling: does post_residual admit the next item exactly?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 25.0; // sets up a perfect closure next step
            } else if slack % 10 == 0 {
                score -= 12.0; // sets up a harmonic residual
            } else if slack < 10 {
                score += 5.0;
