                score -= chain - 90.0 - 5.0 * (14.0 - slack);
            } else {
                score -= chain;
            }
            // Residual can absorb the next item twice.
            if post_residual >= 2 * next_item_size {
                score -= 34.0 * (1.0 - progress);
            }
            if slack == item_size as f64 {
                score -= 40.0;
            }
            // Mutation: residual that can absorb the next item AND the item after
            // a near-exact next fit is extra valuable; deepen the chain reward.
            if next_item_size > 0 && post_residual >= next_item_size + item_size.min(next_item_size) {
