            }
        } else if post_residual > 0 {
            // Blocked residual: penalize proportionally.
            let excess = (post - mean_residual).max(0.0);
            score += 60.0 + 0.78 * excess + 0.30 * (post / cap);
            score += 52.0 * (post / cap) * progress;
            if post < 8.0 && progress > 0.45 {
                score += 14.0;
            }
            if post > next_item_size as f64 * 1.5 && progress < 0.5 {
                score -= 10.0;
            }
            // Mutation: tiny dead-space residuals late in the stream are nearly
            // unusable; add a graduated penalty to steer packing away from them.
            if post < 4.0 {
                score += 9.0 + 2.5 * (4.0 - post) + 12.0 * progress;
