            score += 0.35 * (gap_abs - 20.0) * progress;
        }

        // New: when several bins fit, prefer the one whose post-residual is
        // closest to the next item (sets up the follow-up pairing).
        if fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 {
            let d = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
