        // When the current item leaves a perfect fit for the next item
        // in a fresh bin, make the new bin more attractive.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 60.0 * (1.0 - progress);
        }
        // Large mean residual among open bins means fragmentation is low-cost
        // to consolidate elsewhere; discourage new bins more strongly then.
        if mean_residual / cap > 0.5 && progress > 0.6 {
            score += 35.0;
        }

        // New: late-stream guard — opening a bin near the end is only worth
        // it if the item genuinely cannot be squeezed anywhere well.
        if progress > 0.85 && fitting_bins_count >= 2 {
            score += 45.0 * (progress - 0.85) / 0.15;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = norm_pr * norm_pr * (1.0 + 3.0 * progress) + norm_pr * (1.0 - progress) * 2.0;
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (1.0 + progress) * 4.0;
