pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "friendly" residue classes (multiples of 10, or large enough for
    // typical items) are rewarded; awkward dead-space classes are penalized.
    let cap = bin_capacity as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class A: leftover is a multiple of 10 (harmonic with capacity grid).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 40.0;
    }

    // Class B: leftover can host any future item (>= 80 is prime real estate).
    if post_residual >= 80 {
        score -= 25.0;
    }

    // Class C: dead-space zone — leftover too small for most items (1..10
    // or 11..19 odd sizes). Penalize odd, non-harmonic leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual >= 10 && post_residual < 20 && post_residual % 10 != 0 {
        score += 30.0;
    }

    // Integer-division thresholds: leftover bucket by quarter capacity.
    let quarter = (bin_capacity / 4) as f64;
    let half = (bin_capacity / 2) as f64;
    if (post_residual as f64) > half {
        score -= 15.0; // bin stays flexible
    } else if (post_residual as f64) < quarter && post_residual > 0 {
        score += 20.0; // bin nearly exhausted, poor future utility
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit anywhere else and this bin
    // is the last chance, reward moderately.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual && post_residual - next_item_size < 10 {
            score -= 80.0; // next item leaves near-perfect fit
        } else if next_item_size > post_residual {
            score += 10.0; // next item won't use this bin anyway
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // New-bin candidate (empty bin): only attractive when no open bin fits
    // well — penalize so we prefer filling existing bins unless mean
    // residual across open bins is small.
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: its "post_residual" is capacity - item.
        let fresh_penalty = 120.0
            - 0.5 * mean_residual.max(0.0)
            - (open_bins_count as f64) * 2.0;
        score += fresh_penalty.max(0.0);
        // but if item is large and would leave harmonic leftover, soften.
        if item_size % 10 == 0 {
            score -= 30.0;
        }
    }

    // Late-stream consolidation: near the end, tighten bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (post_residual as f64 / cap);

    // Mild preference for bins below mean residual (balancing).
    score += 0.05 * ((post_residual as f64) - mean_residual);

    score
}

