pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // A residual that cannot hold even the smallest plausible item (<= 10)
    // is pure waste; a residual just below a mid-size item is also bad.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // completely dead space
        } else if post_residual < 25 {
            score += 25.0; // likely unusable gap
        } else if post_residual < 40 {
            score += 8.0;
        }
    } else {
        // Perfect fill is the best outcome.
        score -= 40.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness;

    // If this is the only bin that can fit the item, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual blocks the next item: penalize.
        score += 12.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing
    // ones rather than spreading; penalize candidates less when few bins open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score -= 4.0 * pressure * tightness;

    // New-bin candidate (empty bin): make it unattractive unless it is
    // genuinely better (handled by comparisons), so add a fixed opening cost.
    if bin_residual == bin_capacity {
        score += 45.0 + 5.0 * (open_bins_count as f64);
    }

    // Slight pull toward bins with residual near the mean (balanced packing).
    score += 0.15 * ((bin_residual as f64) - mean_residual).abs();

    score
}

