                score -= chain - 90.0 - 5.0 * (14.0 - slack);
            } else {
                score -= chain;
            }
            // Residual can absorb the next item twice.
            if post_residual >= 2 * next_item_size {
                score -= 34.0 * (1.0 - progress);
            }
            if slack == item_size as f64 {
                score -= 40.0;
            }
            // Reusable space for a second copy of the current item.
            if post_residual >= 2 * item_size && item_size > 0 {
                score -= 12.0 * (1.0 - progress);
            }
            // Dead-space awareness: leftover after next placement should
            // still hold a future item; otherwise penalize proportionally.
            let dead = slack as u32;
            if dead > 0 && dead < item_size.min(next_item_size) {
                score += 18.0 * (dead as f64 / cap) * 10.0 * (1.0 - progress);
            }
        } else if post_residual > 0 {
            // Blocked residual: penalize proportionally.
            let excess = (post - mean_residual).max(0.0);
            score += 60.0 + 0.78 * excess + 0.30 * (post / cap);
            score += 52.0 * (post / cap) * progress;
            if post < 8.0 && progress > 0.45 {
                score += 14.0;
            }
            if post > next_item_size as f64 * 1.5 && progress < 0.5 {
                score -= 10.0;
            }
            // Dead-space penalty scaled by unusability relative to next item.
            let dead = (post - next_item_size as f64).max(0.0);
            score += 0.9 * dead / cap * 100.0 * (1.0 - progress);
        }
    }

    if bin_residual != bin_capacity {
        // Existing bin: reward filling fuller bins, especially late.
        score -= 118.0 * progress;
        score -= 88.0 * tightness * tightness * progress;

        if fitting_bins_count == 1 {
            score -= 78.0;
        } else if fitting_bins_count > 1 {
            score += 3.8 * (fitting_bins_count as f64 - 1.0);
        }

        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 12.0 * dev;

        // Prefer bins whose residual closely matches the item (tight fit).
        let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
        score += 55.0 * fit_gap;

        // After placing, leftover should remain usable for the next item;
        // tiny nonzero leftovers are dead space — penalize.
        if post_residual > 0 && post_residual < next_item_size && next_item_size > 0 {
            score += 26.0 * (1.0 - post / cap) * (1.0 - progress);
        }
        // Fine-grained chain setup: residual divisible by the next item.
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual % next_item_size.max(1)) == 0
            && post_residual != next_item_size {
            score -= 20.0 * (1.0 - progress);
        }
    } else {
        // New-bin candidate: attractive early, costly late.
        let crowding = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 268.0 * progress + 0.58 * mean_residual + 198.0 * crowding;
        score -= 168.0 * (1.0 - progress) * (1.0 - crowding);

        if next_item_size as f64 > 0.6 * cap {
            score -= 48.0;
        }
        if next_item_size > 0 && fitting_bins_count > 1 && next_item_size as f64 > mean_residual.max(0.0) {
            score -= 22.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 1 {
            score -= 30.0 * (1.0 - progress);
        }
        score += 0.20 * open_bins_count as f64 * (mean_residual / cap);
        score += (bin_capacity as f64 - item_size as f64) * 0.05 * progress;

        // Perfect fit for next item in a fresh bin: more attractive.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 60.0 * (1.0 - progress);
        }
        // Large mean residual among open bins: consolidation elsewhere is cheap.
        if mean_residual / cap > 0.5 && progress > 0.6 {
            score += 35.0;
        }
        // Opening a bin for a small item late wastes capacity — penalize.
        if progress > 0.55 {
            let waste = (bin_capacity as f64 - item_size as f64) / cap;
            score += 40.0 * waste * progress;
        }
        // If no open bin fits the next item either, a fresh bin is safer.
        if next_item_size > 0 && fitting_bins_count == 0 {
            score -= 55.0;
        }
        // Fresh bin whose leftover after this item is chainable for the next item.
        if next_item_size > 0 && post_residual >= 2 * next_item_size
            && (post_residual % next_item_size) == 0 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    score
}

