    // Mild penalty for many open bins: encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    // Slight preference for filling fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: neutral-ish, penalized so it's chosen only when fits are terrible.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.5 * item_size as f64;
    }

    score
}

