pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: small post-residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that becomes unusable for typical small items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny slivers are nearly dead space
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 3.0; // medium residual still useful
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 6.0 * (1.0 - (slack_after_next as f64) / 100.0);
        } else {
            // next item won't fit here; slightly penalize wasting a large residual
            let gap = (next_item_size - post_residual) as f64;
            score += 0.05 * gap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a bin is expensive; make the empty-bin
    // call unattractive unless current fits are all poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, modulated by stream progress and
        // how fragmented the open bins are.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 20.0;
        // Late in the stream, prefer consolidating into existing bins.
        new_bin_cost += 10.0 * progress;
        // Many open bins with high mean residual => fragmentation; opening a
        // fresh bin is more acceptable.
        let frag = mean_residual / (bin_capacity as f64);
        new_bin_cost -= 8.0 * frag;
        // If several bins fit, definitely prefer one of them.
        new_bin_cost += 5.0 * (fitting_bins_count as f64);
        score += new_bin_cost;
    }

    // Mild preference for filling bins with larger residual first when many
    // bins are open (keeps bin count low).
    score += 0.02 * (bin_residual as f64) * ((open_bins_count as f64).ln().max(0.0));

