pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits (low post_residual) mildly.
    // Late: penalize wasted residual more aggressively (quartic growth).
    let mut score = pr * (1.0 + 2.0 * progress * progress * progress);

    // Smooth interaction: post_residual normalized against capacity, coupled with progress
    let prn = pr / cap;
    score += 30.0 * prn * prn * (0.5 + progress);

    // Reward bins whose residual becomes nearly perfect (very low post residual)
    score -= 8.0 * (1.0 - prn).powi(12) * (1.0 + progress);

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - prn);
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily (smoothly)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let gapn = gap / cap;
        score += 6.0 * gapn;
        score -= 10.0 * (1.0 - gapn).powi(10) * progress;
    }

    // Mild penalty for many open bins, scaled by mean residual mismatch
    let dev = (mean_residual - pr).abs() / cap;
    score += 2.0 * dev * (open_bins_count as f64).ln().max(1.0);

    // Slight preference toward filling existing bins as stream progresses
    score -= 1.5 * progress * (1.0 - prn);

