pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - post / cap;

    // Exact fill is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead pairing with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 950.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let chain = 235.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 14.0 {
                score -= chain - 90.0 - 5.0 * (14.0 - slack);
            } else {
                score -= chain;
            }
            // Residual can absorb the next item twice.
            if post_residual >= 2 * next_item_size {
                score -= 34.0 * (1.0 - progress);
            }
            if slack == item_size as f64 {
                score -= 40.0;
            }
            // Reusable space for a second copy of the current item.
            if post_residual >= 2 * item_size && item_size > 0 {
                score -= 12.0 * (1.0 - progress);
            }
            // Dead-space awareness: leftover after next placement should
            // still hold a future item; otherwise penalize proportionally.
            let dead = slack as u32;
            if dead > 0 && dead < item_size.min(next_item_size) {
                score += 18.0 * (dead as f64 / cap) * 10.0 * (1.0 - progress);
            }
