        0 => score -= 40.0,              // tiny dead space (<25): nearly full, good
        1 => score += 15.0,              // 25..49: awkward medium gap
        2 => score += 30.0,              // 50..74: half-empty, wasteful
        _ => score += 10.0,              // 75..99: large residual, still reusable
    }

    // Reward if next item fits into post_residual (chain compatibility)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // extra reward if next item then leaves a tiny gap (mod-10 harmonic alignment)
        let after_next = post_residual - next_item_size;
        if after_next % 10 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // next item cannot follow: penalize proportionally
        score += 20.0;
    }

    // Integer-division threshold: post_residual in [1,9] is near-dead space; small gap ok
    if post_residual < 10 {
        score -= 30.0;
    }

    // Last-chance bin: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New empty bin candidate: only attractive when open bins have poor fits
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 60.0;
        // attractive early in the stream or when few bins fit the item
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
        if fitting_bins_count <= 1 {
            score -= 70.0;
        }
        // if current item leaves a nice harmonic gap in a fresh bin, mildly favor it
        if item_size % 10 == 0 {
            score -= 5.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below mean (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Prefer filling bins that are already relatively full
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

