    // strongly favor this bin; if next item cannot fit, penalize slightly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 6.0 + (pr - nxt).abs() * 0.15;
        } else {
            score += 4.0;
