    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: mild preference for tight fits; late: strong avoidance of dead space.
    let w = 0.5 + 1.5 * progress * progress;
    score += w * (pr * pr) / cap;

    // Reward near-perfect fills (small post_residual) super-linearly.
    let tightness = 1.0 - pr / cap;
    score -= (tightness * tightness * tightness) * item_size as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 0.25 * item_size as f64 * (1.0 + progress);
    }

    // Lookahead: if the next item would fit the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Post-residual too small for next item: penalize wasted dead space.
        score += 0.15 * pr * (0.5 + progress);
