pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "reusable"
    // classes (multiples of common small sizes) are more attractive.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -60.0 // perfect fit is always best
    } else if pr % 10 == 0 {
        -20.0
    } else if pr % 5 == 0 {
        -12.0
    } else if pr >= 10 && pr % 2 == 0 {
        -6.0
    } else if pr < 10 {
        25.0 // tiny dead space penalty
    } else {
        0.0
    };
    score += class_bonus;

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Harmonic match: next item's complement class
            let gap = pr - next_item_size;
            if gap % 10 == 0 {
                score -= 18.0;
            } else if gap <= 10 {
                score -= 8.0;
            } else {
                score -= 4.0;
            }
        } else {
            // next item won't fit here: penalize proportionally to overflow
            score += ((next_item_size - pr) as f64) * 0.5;
        }
    } else {
        // last item: just minimize post residual
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a moderate base cost so it is
    // only chosen when open bins have poor fits.
    if bin_residual == bin_capacity {
        score += 45.0 + 0.1 * open_bins_count as f64;
    } else {
        // Prefer tighter (fuller) bins slightly: reward proximity of residual to item
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += tightness * 10.0;
