    // Stream progression: late in stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - pr as f64).abs().min(20.0);

    // Penalize deviating far below mean residual (wasteful use of a roomy bin)
    if (pr as f64) < mean_residual * 0.5 && bin_residual < bin_capacity {
        score += 8.0;
    }

