        // to opening one for a small item mid-stream.
        if item_frac > 0.5 && progress > 0.35 && progress < 0.75 {
            score -= 16.0 * item_frac * remaining;
        }
        // NEW: discourage opening a fresh bin when an existing bin would be
        // left with a perfectly chainable residual (preserve chain setups).
        if fitting_bins_count > 0 && post_residual > next_item_size as u32 {
            score += 14.0 * remaining;
        }
    }

    score
}

