            }
            if post < item_size as f64 {
                score += 26.0 * (1.0 - post / cap) * (0.4 + 0.6 * progress);
            }
            if post < item_size as f64 && post < next_item_size as f64 {
                score += 25.0 * (1.0 - post / cap);
            }
            let dead = (post - next_item_size as f64).max(0.0);
            score += 90.0 * dead / cap * remaining;
            if fitting_bins_count > 2 {
                score += 8.0 * (fitting_bins_count.min(6) as f64 - 2.0);
            }
            let usable_frac = post / cap;
            if usable_frac > 0.45 {
                score -= 20.0 * (usable_frac - 0.45) * remaining;
            }
            if post > next_item_size as f64 * 0.75 && post < next_item_size as f64 {
                score -= 8.0 * remaining;
            }
        }
    }

    if bin_residual != bin_capacity {
        // Existing bin: reward filling fuller bins, especially late.
        score -= 118.0 * progress;
        score -= 88.0 * tightness * tightness * progress;

        if fitting_bins_count == 1 {
            score -= 78.0;
        } else if fitting_bins_count > 1 {
            score += 3.8 * (fitting_bins_count as f64 - 1.0);
        }

        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 12.0 * dev;

        // Prefer bins whose residual closely matches the item (tight fit).
        let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
        score += 55.0 * fit_gap;

        if bin_residual == item_size {
            score -= 30.0 * (0.5 + progress);
            if progress > 0.5 {
                score -= 25.0 * progress;
            }
        }

        // Tiny nonzero leftovers are dead space — penalize.
        if post_residual > 0 && post_residual < next_item_size {
            score += 26.0 * (1.0 - post / cap) * remaining;
        }
        if post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
            score += 18.0 * remaining;
        }
        if post_residual > 0 && post_residual < item_size.min(next_item_size).max(1) {
            score += 34.0 * (1.0 - post / cap) * (0.3 + 0.7 * progress);
            score += 18.0 * progress * progress;
        }
        if post_residual >= next_item_size
            && (post_residual % next_item_size.max(1)) == 0
            && post_residual != next_item_size {
            score -= 20.0 * remaining;
        }
        let post_dev = (post - mean_residual) / cap;
        score += 9.0 * post_dev * remaining;
        if post_residual > 0 && post_residual < 6 && progress > 0.6 {
            score += 10.0 * progress;
        }
        if fitting_bins_count <= 2 && post_residual > 0 {
            score -= 14.0 * tightness * remaining;
        }
        if post_residual >= next_item_size {
            let near = (post_residual - next_item_size) as f64;
            if near <= 3.0 {
                score -= 16.0 * (3.0 - near) * remaining;
            } else if near <= 8.0 {
                score -= 5.0 * (8.0 - near) * remaining;
            }
        }
        if post_residual > 0 && bin_residual > item_size {
            let leftover = (bin_residual - item_size) as f64;
            score += 20.0 * (leftover / cap) * (0.5 + progress);
        }
        if post_residual > 0 && post_residual < next_item_size && open_bins_count > 3 {
            score += 10.0 * (open_bins_count.min(10) as f64 - 3.0) * (1.0 - post / cap) * remaining;
        }
        // Residual-efficiency coupling: consuming a large share of the
        // residual keeps bins tight and reduces fragmentation.
        if bin_residual > 0 {
            let consume = item_size as f64 / bin_residual as f64;
            score -= 14.0 * consume * (0.4 + 0.6 * progress);
        }
        // Awkward-middle residual band penalized with open-bin pressure.
        if post_residual > 0
            && post_residual as f64 > 0.18 * cap
            && post_residual < next_item_size.max(item_size)
            && open_bins_count > 2 {
            score += 12.0 * (open_bins_count.min(8) as f64 - 2.0) * remaining;
        }
        // MUTATION: prefer bins whose post-residual is itself a tight
        // leftover (post close to next item or zero) — graded by how
        // close post is to the smallest useful future footprint.
        if post_residual > 0 && post_residual >= next_item_size {
            let post_gap = (post_residual - next_item_size) as f64;
            score += 6.0 * (post_gap / cap) * progress;
        }
    } else {
        // New-bin candidate: attractive early, costly late.
        let crowding = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 268.0 * progress + 0.58 * mean_residual + 198.0 * crowding;
        score -= 168.0 * remaining * (1.0 - crowding);

        if next_item_size as f64 > 0.6 * cap {
            score -= 48.0;
        }
        if fitting_bins_count > 1 && next_item_size as f64 > mean_residual.max(0.0) {
            score -= 22.0 * remaining;
        }
        if fitting_bins_count <= 1 {
            score -= 30.0 * remaining;
        }
        score += 0.20 * open_bins_count as f64 * (mean_residual / cap);
        score += (cap - item_size as f64) * 0.05 * progress;

        if post_residual == next_item_size {
            score -= 60.0 * remaining;
        }
        if mean_residual / cap > 0.5 && progress > 0.6 {
            score += 35.0;
        }
        if progress > 0.55 {
            let waste = (cap - item_size as f64) / cap;
            score += 40.0 * waste * progress;
        }
        let item_frac = item_size as f64 / cap;
        if item_frac > 0.6 && progress < 0.4 {
            score -= 24.0 * item_frac * remaining;
        }
        if item_frac > 0.5 && progress > 0.35 && progress < 0.75 {
            score -= 16.0 * item_frac * remaining;
        }
        if item_frac < 0.25 && progress > 0.5 {
            score += 18.0 * (0.25 - item_frac) * 4.0 * progress;
        }
        if item_frac < 0.2 && progress > 0.4 {
            score += 30.0 * (0.2 - item_frac) * progress;
        }
        if fitting_bins_count == 0 {
            score -= 55.0;
        }
        if post_residual >= 2 * next_item_size
            && (post_residual % next_item_size.max(1)) == 0 {
            score -= 25.0 * remaining;
        }
        if fitting_bins_count > 0 && post_residual > next_item_size {
            score += 14.0 * remaining;
        }
        if post_residual > 0 && post_residual < next_item_size {
            score += 24.0 * remaining;
        }
        if post_residual > 0
            && post_residual < item_size.min(next_item_size).max(1)
            && progress > 0.3 {
            score += 20.0 * (0.3 + 0.7 * progress);
        }
        if item_frac > 0.5 && mean_residual / cap < 0.3 {
            score -= 20.0 * item_frac * remaining;
        }
        if bin_capacity - item_size == next_item_size {
            score -= 45.0 * remaining;
        }
        if post_residual > 0
            && post_residual < next_item_size
            && mean_residual / cap < 0.25
            && fitting_bins_count > 0 {
            score += 30.0 * remaining;
        }
        if item_frac > 0.4
            && next_item_size > 0
            && post_residual >= 2 * next_item_size
            && post_residual % next_item_size == 0 {
            score -= 18.0 * remaining;
        }
        // MUTATION: fresh bin for a small item whose leftover leaves a
        // large stranded residual mid-stream is wasteful when open bins
        // already have room to absorb the next item.
        if item_frac < 0.3
            && progress > 0.35
            && fitting_bins_count > 0
            && mean_residual / cap > item_frac {
            score += 22.0 * remaining;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let remaining = 1.0 - progress;
    let tightness = 1.0 - post / cap;

    // Exact fill is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead pairing with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 950.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let chain = 235.0 * (1.0 - slack / cap);
            if slack < 14.0 {
                score -= chain - 90.0 - 5.0 * (14.0 - slack);
            } else {
                score -= chain;
            }
            if post_residual >= 2 * next_item_size {
                score -= 34.0 * remaining;
            }
            if post_residual == 2 * next_item_size {
                score -= 55.0 * remaining;
            }
            if post_residual >= 3 * next_item_size && next_item_size <= bin_capacity / 4 {
                score -= 22.0 * remaining;
            }
            if next_item_size > 1 && post_residual % next_item_size == 0 {
                score -= 15.0 * remaining;
            }
            if slack as u32 == item_size {
                score -= 40.0;
            }
            if post_residual >= 2 * item_size {
                score -= 12.0 * remaining;
            }
            if slack > 0.0 {
                score -= 18.0 * (slack / cap) * remaining;
            }
            let dead = slack as u32;
            if dead > 0 && dead < item_size.min(next_item_size) {
                score += 185.0 * (dead as f64 / cap) * (0.4 + 0.6 * progress);
            }
            // Sharpened reward band for slack in [1, 6]: near-perfect leftovers.
            if dead >= 1 && dead <= 6 {
                score -= 12.0 * remaining;
            }
            // Exact double/triple fit for next item is a perfect chain.
            if post_residual == 3 * next_item_size {
                score -= 30.0 * remaining;
            }
            // Slack that still fits a second copy of the next item is a
            // strong chain setup; scale reward with how many copies fit.
            let copies = dead / next_item_size.max(1);
            if copies >= 2 {
                score -= 9.0 * (copies.min(4) as f64) * remaining;
            }
            // Reward residuals that can absorb the next item plus a
            // small filler, reducing future dead space in this bin.
            if dead > 0 && dead < next_item_size && dead <= item_size {
                score -= 14.0 * remaining;
            }
            // Two-step lookahead — if the post-residual after placing
            // the next item can also host a second copy, this bin becomes a
            // near-perfect multi-item container; reward proportionally.
            if post_residual >= 2 * next_item_size {
                let after2 = post_residual - 2 * next_item_size;
                if after2 == 0 {
                    score -= 48.0 * remaining;
                } else if after2 < next_item_size {
                    score -= 10.0 * remaining;
                    score += 20.0 * (after2 as f64 / cap);
                }
            }
            let dead_ratio = dead as f64 / post_residual.max(1) as f64;
            if dead > 0 {
                score += 26.0 * dead_ratio * (0.35 + 0.65 * progress);
            }
            // Reusability: leftover still fits another copy of the current
            // item's size class — the bin stays productive.
            if dead >= item_size.min(next_item_size).max(1) && dead as f64 <= cap * 0.35 {
                score -= 10.0 * (1.0 - dead as f64 / (cap * 0.35)) * remaining;
            }
            // NEW: residual-efficiency refinement — when the post residual
            // is a near-perfect multiple of the next item (low dead ratio)
            // AND the stream is late, deepen the chain reward to squeeze
            // out the last bins from residual fragmentation.
            if dead > 0 && dead_ratio < 0.25 && progress > 0.5 {
                score -= 9.0 * (1.0 - dead_ratio) * remaining;
            }
            // NEW: penalize mid-band slack that is too small for the next
            // item but too large to ignore, late in the stream.
            if dead > next_item_size.max(6) && dead < 3 * next_item_size && dead < item_size {
                score += 12.0 * (dead as f64 / cap) * progress;
            }
        } else if post_residual > 0 {
            // Blocked residual: penalize proportionally.
            let excess = (post - mean_residual).max(0.0);
            score += 60.0 + 0.78 * excess + 30.0 * (post / cap);
            score += 52.0 * (post / cap) * progress;
            if post < 8.0 && progress > 0.45 {
                score += 14.0;
            }
            if post > next_item_size as f64 * 1.5 && progress < 0.5 {
                score -= 10.0;
            }
            if post < item_size as f64 {
                score += 26.0 * (1.0 - post / cap) * (0.4 + 0.6 * progress);
            }
            if post < item_size as f64 && post < next_item_size as f64 {
                score += 25.0 * (1.0 - post / cap);
            }
            let dead = (post - next_item_size as f64).max(0.0);
            score += 90.0 * dead / cap * remaining;
            if fitting_bins_count > 2 {
                score += 8.0 * (fitting_bins_count.min(6) as f64 - 2.0);
            }
            let usable_frac = post / cap;
            if usable_frac > 0.45 {
                score -= 20.0 * (usable_frac - 0.45) * remaining;
            }
            if post > next_item_size as f64 * 0.75 && post < next_item_size as f64 {
                score -= 8.0 * remaining;
            }
            // NEW: a blocked residual that is a multiple of the current
            // item can still pack repeats of THIS item later — soften the
            // penalty by the number of such copies.
            if item_size > 0 && post_residual >= item_size {
                let rep = post_residual / item_size;
                if rep >= 2 {
                    score -= 7.0 * (rep.min(4) as f64) * remaining;
                }
            }
        }
    }

    if bin_residual != bin_capacity {
        // Existing bin: reward filling fuller bins, especially late.
        score -= 118.0 * progress;
        score -= 88.0 * tightness * tightness * progress;

        if fitting_bins_count == 1 {
            score -= 78.0;
        } else if fitting_bins_count > 1 {
            score += 3.8 * (fitting_bins_count as f64 - 1.0);
        }

        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 12.0 * dev;

        // Prefer bins whose residual closely matches the item (tight fit).
        let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
        score += 55.0 * fit_gap;

        if bin_residual == item_size {
            score -= 30.0 * (0.5 + progress);
            if progress > 0.5 {
                score -= 25.0 * progress;
            }
        }

        // Tiny nonzero leftovers are dead space — penalize.
        if post_residual > 0 && post_residual < next_item_size {
            score += 26.0 * (1.0 - post / cap) * remaining;
        }
        if post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
            score += 18.0 * remaining;
        }
        // Leftover smaller than the running minimum item scale is
        // unrecoverable dead space; penalize harder as the stream advances.
        if post_residual > 0 && post_residual < item_size.min(next_item_size).max(1) {
            score += 34.0 * (1.0 - post / cap) * (0.3 + 0.7 * progress);
            score += 18.0 * progress * progress;
        }
        // Chain setup: residual divisible by the next item.
        if post_residual >= next_item_size
            && (post_residual % next_item_size.max(1)) == 0
            && post_residual != next_item_size {
            score -= 20.0 * remaining;
        }
        let post_dev = (post - mean_residual) / cap;
        score += 9.0 * post_dev * remaining;
        if post_residual > 0 && post_residual < 6 && progress > 0.6 {
            score += 10.0 * progress;
        }
        // When few bins remain viable, protect the tightest fits.
        if fitting_bins_count <= 2 && post_residual > 0 {
            score -= 14.0 * tightness * remaining;
        }
        // Graded bonus for near-exact residuals relative to next item.
        if post_residual >= next_item_size {
            let near = (post_residual - next_item_size) as f64;
            if near <= 3.0 {
                score -= 16.0 * (3.0 - near) * remaining;
            } else if near <= 8.0 {
                score -= 5.0 * (8.0 - near) * remaining;
            }
        }
        // Prefer placing items into bins whose residual exceeds the
        // item by the smallest amount (minimizes leftover), stronger late.
        if post_residual > 0 && bin_residual > item_size {
            let leftover = (bin_residual - item_size) as f64;
            score += 20.0 * (leftover / cap) * (0.5 + progress);
        }
        // Dead-space ratio guard — bins whose post-residual is small
        // but nonzero AND below the next item's size are stranding capacity;
        // escalate this penalty when many bins are open (fragmentation risk).
        if post_residual > 0 && post_residual < next_item_size && open_bins_count > 3 {
            score += 10.0 * (open_bins_count.min(10) as f64 - 3.0) * (1.0 - post / cap) * remaining;
        }
        // Residual-efficiency coupling — a placement consuming a large
        // share of the residual keeps bins tight and reduces fragmentation.
        if bin_residual > 0 {
            let consume = item_size as f64 / bin_residual as f64;
            score -= 14.0 * consume * (0.4 + 0.6 * progress);
        }
        // Penalize bins left with a residual in the "awkward middle"
        // band — too large to ignore, too small to reliably host typical
        // items; strength grows with open-bin count.
        if post_residual > 0
            && post_residual as f64 > 0.18 * cap
            && post_residual < next_item_size.max(item_size)
            && open_bins_count > 2 {
            score += 12.0 * (open_bins_count.min(8) as f64 - 2.0) * remaining;
        }
        // NEW: endgame consolidation — when the stream is nearly done and
        // the post residual can host the next item exactly, deepen the
        // reward so the final bins close out near-perfectly.
        if progress > 0.8 && post_residual == next_item_size.max(1) {
            score -= 20.0 * remaining;
        }
        // NEW: late-stream residual variance control — prefer bins whose
        // post residual stays close to the mean, avoiding outlier gaps.
        if progress > 0.65 {
            let pd = ((post - mean_residual) / cap).abs();
            score += 8.0 * pd * remaining;
        }
    } else {
        // New-bin candidate: attractive early, costly late.
        let crowding = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 268.0 * progress + 0.58 * mean_residual + 198.0 * crowding;
        score -= 168.0 * remaining * (1.0 - crowding);

        if next_item_size as f64 > 0.6 * cap {
            score -= 48.0;
        }
        if fitting_bins_count > 1 && next_item_size as f64 > mean_residual.max(0.0) {
            score -= 22.0 * remaining;
        }
        if fitting_bins_count <= 1 {
            score -= 30.0 * remaining;
        }
        score += 0.20 * open_bins_count as f64 * (mean_residual / cap);
        score += (cap - item_size as f64) * 0.05 * progress;

        if post_residual == next_item_size {
            score -= 60.0 * remaining;
        }
        if mean_residual / cap > 0.5 && progress > 0.6 {
            score += 35.0;
        }
        // Opening a bin for a small item late wastes capacity — penalize.
        if progress > 0.55 {
            let waste = (cap - item_size as f64) / cap;
            score += 40.0 * waste * progress;
        }
        let item_frac = item_size as f64 / cap;
        if item_frac > 0.6 && progress < 0.4 {
            score -= 24.0 * item_frac * remaining;
        }
        if item_frac > 0.5 && progress > 0.35 && progress < 0.75 {
            score -= 16.0 * item_frac * remaining;
        }
        if item_frac < 0.25 && progress > 0.5 {
            score += 18.0 * (0.25 - item_frac) * 4.0 * progress;
        }
        // Opening a fresh bin for a tiny item mid/late stream is pure waste.
        if item_frac < 0.2 && progress > 0.4 {
            score += 30.0 * (0.2 - item_frac) * progress;
        }
        // If no open bin fits the next item either, a fresh bin is safer.
        if fitting_bins_count == 0 {
            score -= 55.0;
        }
        // Fresh bin whose leftover is chainable for the next item.
        if post_residual >= 2 * next_item_size
            && (post_residual % next_item_size.max(1)) == 0 {
            score -= 25.0 * remaining;
        }
        if fitting_bins_count > 0 && post_residual > next_item_size {
            score += 14.0 * remaining;
        }
        // A fresh bin is worthwhile only if the item leaves a residual
        // that can plausibly host the next item; otherwise penalize.
        if post_residual > 0 && post_residual < next_item_size {
            score += 24.0 * remaining;
        }
        // Penalize fresh bins whose leftover would be dead space.
        if post_residual > 0
            && post_residual < item_size.min(next_item_size).max(1)
            && progress > 0.3 {
            score += 20.0 * (0.3 + 0.7 * progress);
        }
        // Fresh bin for a large item leaves a large residual that many
        // future items can use — reward when mean residual is small.
        if item_frac > 0.5 && mean_residual / cap < 0.3 {
            score -= 20.0 * item_frac * remaining;
        }
        // Opening a fresh bin is more attractive when the leftover
        // (cap - item) is exactly the next item size — perfect chain.
        if bin_capacity - item_size == next_item_size {
            score -= 45.0 * remaining;
        }
        // Fresh-bin dead-space audit — if the leftover after this item
        // cannot host the next item AND the mean residual across open bins
        // is small (open bins are already tight), opening a new bin strands
        // capacity; make it clearly unattractive.
        if post_residual > 0
            && post_residual < next_item_size
            && mean_residual / cap < 0.25
            && fitting_bins_count > 0 {
            score += 30.0 * remaining;
        }
        // Fresh-bin utilization audit — opening a bin for a large item
        // with a residual that is a clean multiple of the next item is a
        // strong multi-slot container; reward it, stronger early/mid stream.
        if item_frac > 0.4
            && next_item_size > 0
            && post_residual >= 2 * next_item_size
            && post_residual % next_item_size == 0 {
            score -= 18.0 * remaining;
        }
        // NEW: fresh-bin leftover coverage audit — when the fresh bin's
        // post residual exceeds the mean residual by a wide margin, the
        // new bin dominates existing capacity; reward this coverage.
        if post_residual as f64 > mean_residual + 0.3 * cap && fitting_bins_count > 0 {
            score -= 12.0 * remaining;
        }
    }

    score
}

