            // after taking both items is small AND reusable (>= min item
            // scale), punish stranded fragments with a sharper curve.
            if post_residual >= item_size + next_item_size {
                let after_pair = post_residual - item_size - next_item_size;
                let min_scale = item_size.min(next_item_size);
                if after_pair >= min_scale {
                    // reinforced: sharper gradient, later-stream emphasis
                    score -= 13.0 * remaining * (1.0 - after_pair as f64 / cap)
                        + 6.0 * progress * (1.0 - after_pair as f64 / cap);
                } else if after_pair > 0 && after_pair < min_scale {
                    // stranded fragment: punish harder as stream closes
                    score += 22.0 * (after_pair as f64 / cap) * (0.5 + 0.5 * progress);
                }
            }
