            // next item exactly three times late in the stream is a
            // near-perfect compaction target.
            if post_residual == 3 * next_item_size && progress > 0.55 {
                score -= 18.0 * remaining;
            }
            // MUTATION: divisibility chain lookahead — residual that can be
            // tiled by the next item with zero waste for 2+ steps is a
            // compaction magnet; scale reward by how many copies fit.
            if next_item_size > 1 && post_residual % next_item_size == 0 {
                let tiles = post_residual / next_item_size;
                if tiles >= 2 {
                    score -= 11.0 * (tiles.min(5) as f64) * remaining * (0.5 + 0.5 * progress);
