        if progress > 0.5 && post_residual >= 2 * next_item_size.min(item_size).max(1) {
            score -= 12.0 * remaining;
        }
        if item_frac > 0.45 && fitting_bins_count == 0 {
            score -= 18.0 * remaining;
        }
    }

    score
}

