        // that can hold the next item twice.
        if post_residual == next_item_size && progress > 0.35 {
            score -= 26.0 * remaining;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 16.0 * remaining;
        }
