        // deserve a fresh bin rather than wedging into a crowded fit.
        if item_frac > 0.55 && progress > 0.6 && mean_residual / cap < 0.3 {
            score -= 24.0 * item_frac * remaining;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let remaining = 1.0 - progress;
    let tightness = 1.0 - post / cap;

    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead pairing with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let chain = 220.0 * (1.0 - slack / cap);
            if slack < 14.0 {
                score -= chain - 80.0 - 5.0 * (14.0 - slack);
            } else {
                score -= chain;
            }
            if post_residual >= 2 * next_item_size {
                score -= 32.0 * remaining;
            }
            if post_residual == 2 * next_item_size {
                score -= 50.0 * remaining;
            }
            if next_item_size > 1 && post_residual % next_item_size == 0 {
                score -= 14.0 * remaining;
            }
            if slack as u32 == item_size {
                score -= 38.0;
            }
            let dead = slack as u32;
            if dead > 0 && dead < item_size.min(next_item_size) {
                score += 175.0 * (dead as f64 / cap) * (0.4 + 0.6 * progress);
            }
            if dead >= 1 && dead <= 6 {
                score -= 11.0 * remaining;
            }
            if post_residual == 3 * next_item_size {
                score -= 28.0 * remaining;
            }
            let dead_ratio = dead as f64 / post_residual.max(1) as f64;
            if dead > 0 {
                score += 24.0 * dead_ratio * (0.35 + 0.65 * progress);
            }
            if post_residual >= item_size + next_item_size {
                let after_pair = post_residual - item_size - next_item_size;
                if after_pair == 0 {
                    score -= 22.0 * remaining;
                } else if after_pair <= 4 {
                    score -= 9.0 * remaining;
                } else if after_pair < item_size.min(next_item_size) {
                    score += 8.0 * (after_pair as f64 / cap) * remaining;
                } else {
                    score -= 8.0 * remaining * (1.0 - after_pair as f64 / cap);
                }
            }
        } else if post_residual > 0 {
            // Residual blocked relative to next item.
            let excess = (post - mean_residual).max(0.0);
            score += 55.0 + 0.7 * excess + 28.0 * (post / cap);
            score += 48.0 * (post / cap) * progress;
            if post < item_size as f64 {
                score += 24.0 * (1.0 - post / cap) * (0.4 + 0.6 * progress);
            }
            let dead = (post - next_item_size as f64).max(0.0);
            score += 85.0 * dead / cap * remaining;
            if fitting_bins_count > 2 {
                score += 7.0 * (fitting_bins_count.min(6) as f64 - 2.0);
            }
            let usable_frac = post / cap;
            if usable_frac > 0.45 {
                score -= 18.0 * (usable_frac - 0.45) * remaining;
            }
            if fitting_bins_count == 1 {
                score -= 45.0 + 20.0 * (post / cap);
            }
            let dev = ((post - mean_residual) / cap).abs();
            score += 9.0 * dev * remaining;
        }
    }

    if bin_residual != bin_capacity {
        score -= 110.0 * progress;
        score -= 85.0 * tightness * tightness * progress;

        if fitting_bins_count == 1 {
            score -= 75.0;
        } else if fitting_bins_count > 1 {
            score += 3.5 * (fitting_bins_count as f64 - 1.0);
        }

        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 11.0 * dev;

        let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
        score += 52.0 * fit_gap;

        if bin_residual == item_size {
            score -= 30.0 * (0.5 + progress);
        }

        if post_residual > 0 && post_residual < item_size.min(next_item_size).max(1) {
            score += 32.0 * (1.0 - post / cap) * (0.3 + 0.7 * progress);
            score += 16.0 * progress * progress;
        }
        if post_residual >= next_item_size
            && (post_residual % next_item_size.max(1)) == 0
            && post_residual != next_item_size {
            score -= 18.0 * remaining;
        }
        let post_dev = (post - mean_residual) / cap;
        score += 8.0 * post_dev * remaining;
        if post_residual > 0 && post_residual < 6 && progress > 0.6 {
            score += 10.0 * progress;
        }
        if fitting_bins_count <= 2 && post_residual > 0 {
            score -= 13.0 * tightness * remaining;
        }
        if post_residual >= next_item_size {
            let near = (post_residual - next_item_size) as f64;
            if near <= 3.0 {
                score -= 15.0 * (3.0 - near) * remaining;
            } else if near <= 8.0 {
                score -= 5.0 * (8.0 - near) * remaining;
            }
        }
        if bin_residual > 0 {
            let consume = item_size as f64 / bin_residual as f64;
            score -= 13.0 * consume * (0.4 + 0.6 * progress);
        }
        if post_residual > 0
            && post_residual as f64 > 0.18 * cap
            && post_residual < next_item_size.max(item_size)
            && open_bins_count > 2 {
            score += 11.0 * (open_bins_count.min(8) as f64 - 2.0) * remaining;
        }
        if progress > 0.6 && post_residual >= 1 && post_residual <= 4 {
            score -= 9.0 * (5.0 - post as f64) * remaining;
        }
        // Near-exact fill gradient.
        if bin_residual > 0 {
            let fill = item_size as f64 / bin_residual as f64;
            if fill > 0.8 && progress > 0.4 {
                score -= 20.0 * (fill - 0.8) * 5.0 * remaining;
            }
        }
    } else {
        // NEW-BIN CANDIDATE branch.
        let crowding = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 260.0 * progress + 0.55 * mean_residual + 190.0 * crowding;
        score -= 160.0 * remaining * (1.0 - crowding);

        if next_item_size as f64 > 0.6 * cap {
            score -= 45.0;
        }
        if fitting_bins_count > 1 && next_item_size as f64 > mean_residual.max(0.0) {
            score -= 20.0 * remaining;
        }
        if fitting_bins_count <= 1 {
            score -= 28.0 * remaining;
        }
        score += 0.20 * open_bins_count as f64 * (mean_residual / cap);
        score += (cap - item_size as f64) * 0.05 * progress;

        if post_residual == next_item_size {
            score -= 55.0 * remaining;
        }
        if progress > 0.55 {
            let waste = (cap - item_size as f64) / cap;
            score += 38.0 * waste * progress;
        }
        let item_frac = item_size as f64 / cap;
        if item_frac > 0.6 && progress < 0.4 {
            score -= 22.0 * item_frac * remaining;
        }
        if item_frac < 0.2 && progress > 0.4 {
            score += 28.0 * (0.2 - item_frac) * progress;
        }
        if fitting_bins_count == 0 {
            score -= 52.0;
        }
        if post_residual >= 2 * next_item_size
            && (post_residual % next_item_size.max(1)) == 0 {
            score -= 24.0 * remaining;
        }
        if fitting_bins_count > 0 && post_residual > next_item_size {
            score += 13.0 * remaining;
        }
        if post_residual > 0 && post_residual < next_item_size {
            score += 23.0 * remaining;
        }
        if item_frac > 0.5 && mean_residual / cap < 0.3 {
            score -= 18.0 * item_frac * remaining;
        }
        if bin_capacity - item_size == next_item_size {
            score -= 42.0 * remaining;
        }
        if post_residual > 0
            && post_residual < next_item_size
            && mean_residual / cap < 0.25
            && fitting_bins_count > 0 {
            score += 28.0 * remaining;
        }
        if mean_residual / cap > 0.35 && item_frac < 0.5 && progress > 0.3 {
            score += 17.0 * (mean_residual / cap) * remaining;
        }
        if next_item_size as f64 > 0.5 * cap
            && post_residual >= next_item_size
            && fitting_bins_count > 0 {
            score -= 24.0 * remaining;
        }
        // Fleet saturation guard: don't force bad fits into nearly-exhausted bins.
        if mean_residual / cap < 0.08 && fitting_bins_count > 0 && progress > 0.5 {
            score -= 28.0 * remaining * (0.08 - mean_residual / cap) * 12.5;
        }
    }

    score
}

