    if post_residual >= 80 {
        score -= 18.0 * remaining;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 55.0 * (0.5 + 0.5 * progress);
    }
    if post_residual >= 10 && post_residual < 20 && post_residual % 10 != 0 {
        score += 25.0 * remaining;
    }

    let quarter = cap * 0.25;
    let half = cap * 0.5;
    if post > half {
        score -= 12.0 * remaining;
    } else if post > 0.0 && post < quarter {
        score += 18.0 * remaining;
    }

    // Lookahead pairing with the next item (borrowed from best heuristic).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
