            score -= 7.0 * remaining;
        }
        if fitting_bins_count <= 2 && post_residual > 0 {
            score -= 12.0 * tightness * remaining;
        }
        if progress > 0.65 {
            let pd = ((post - mean_residual) / cap).abs();
            score += 7.0 * pd * remaining;
        }
    }

    // Late-stream consolidation: tighten bins harder near the end.
    score -= progress * 8.0 * (post / cap);

    // Mild balancing toward mean residual.
    score += 0.05 * (post - mean_residual);

    score
}

