        if mean_residual / cap < 0.08 && fitting_bins_count > 0 && progress > 0.5 {
            score -= 28.0 * remaining * (0.08 - mean_residual / cap) * 12.5;
        }
        // Fresh-bin salvage: a brand-new bin whose leftover exactly hosts
        // the next item makes opening cheap even mid-stream.
        if bin_capacity - item_size == next_item_size && progress > 0.35 {
            score -= 13.0 * remaining;
        }
        // Dead-space ratio guard: preserve usable space for the lookahead
        // when the fleet's mean residual is small relative to next item.
        if next_item_size > 0
            && mean_residual > 0.0
            && (mean_residual / next_item_size as f64) < 0.5
            && fitting_bins_count > 0
            && progress > 0.4 {
            score -= 15.0 * remaining * (1.0 - mean_residual / next_item_size as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly discount small post-residuals (dead space).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize post-residuals that are too small to be useful later
    // (dead space below the smallest plausible item), unless it's an exact fit.
    if post_residual > 0 {
        let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 2.5;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item could use this bin's post-residual exactly,
    // reward leaving that space; if next item can't fit post-residual, penalize.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let pr = post_residual as f64;
        if n <= pr {
            // next item fits here afterwards: good chaining
            let chain_fit = 1.0 - ((pr - n) / bin_capacity as f64);
            score -= 12.0 * chain_fit;
        } else {
            // next item won't fit here: leftover space is more likely wasted
            score += (n - pr).min(bin_capacity as f64) * 0.15;
        }
    }

    // Time horizon: early in the stream, be conservative (prefer filling existing
    // bins to keep many options); late in the stream, prioritize tight packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins below the mean residual (balancing), or open new bins if all are tight.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    let mean_fill = 1.0 - mean_residual / bin_capacity as f64;
    score += (fill_ratio - mean_fill) * 8.0;

    // If bin is a brand-new empty bin candidate: penalize moderately so it's chosen
    // only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if open bins are all quite full (low mean residual), opening new is fine.
        score -= mean_fill * 15.0;
        // Late in stream with many bins, opening new bins is less costly.
        score -= 10.0 * progress;
    }

    // Slight penalty for very large open_bins_count to encourage consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
