        }
        if item_frac > 0.4
            && next_item_size > 0
            && post_residual >= 2 * next_item_size
            && post_residual % next_item_size == 0 {
            score -= 18.0 * remaining;
        }
        if post_residual as f64 > mean_residual + 0.3 * cap && fitting_bins_count > 0 {
            score -= 12.0 * remaining;
        }
        if post_residual > 0
            && post_residual < next_item_size
            && (post_residual as f64) > 0.5 * cap
            && progress > 0.5 {
            score += 26.0 * remaining;
        }
        if next_item_size > 0 && post_residual >= 3 * next_item_size {
            score -= 14.0 * remaining;
        }
        if post_residual % 10 == 0 && post_residual > 0 {
            score -= 12.0 * remaining;
        }
        if mean_residual / cap > 0.35 && item_frac < 0.5 && progress > 0.3 {
            score += 18.0 * (mean_residual / cap) * remaining;
        }
        if item_frac < 0.35 && fitting_bins_count > 0 && progress < 0.6 {
            score += 22.0 * (1.0 - item_frac) * (fitting_bins_count.min(5) as f64) * remaining;
        }
        if next_item_size as f64 > 0.5 * cap
            && post_residual >= next_item_size
            && fitting_bins_count > 0 {
            score -= 26.0 * remaining;
        }
        if bin_capacity - item_size == next_item_size && progress > 0.5 {
            score -= 20.0 * remaining;
        }
        // MUTATION: fleet saturation guard — when open bins are nearly
        // exhausted (tiny mean residual), don't force bad fits into them.
        if mean_residual / cap < 0.08 && fitting_bins_count > 0 && progress > 0.5 {
            score -= 30.0 * remaining * (0.08 - mean_residual / cap) * 12.5;
        }
        // MUTATION: dead-space ratio guard — when the fleet's mean residual
        // is small relative to the next item, opening a fresh bin preserves
        // usable space for the lookahead instead of scattering it.
        if next_item_size > 0
            && mean_residual > 0.0
            && (mean_residual / next_item_size as f64) < 0.5
            && fitting_bins_count > 0
            && progress > 0.4 {
            score -= 16.0 * remaining * (1.0 - mean_residual / next_item_size as f64);
        }
        // MUTATION: fresh-bin leftover utility — a new bin's leftover should
        // be large enough to remain reusable; penalize nearly-full placements
        // that strand a sliver of space.
        let fresh_left = bin_capacity - item_size;
        if fresh_left > 0 && fresh_left < item_size.min(next_item_size).max(1) {
            score += 28.0 * remaining;
        }
        if fresh_left >= 2 * next_item_size && fresh_left <= 3 * next_item_size {
            score -= 12.0 * remaining;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio, non-linearly amplified by stream progress
    let fill = item_size as f64 / bin_capacity as f64;
    let tightness = (1.0 - post_residual as f64 / bin_capacity as f64).powi(2);
    score -= 40.0 * fill * tightness * (0.5 + progress);

    // Penalize small dead space (unusable slivers), smoothly scaled by progress
    let dead = post_residual as f64;
    let sliver = (-((dead / 20.0).powi(2))).exp();
    score += 25.0 * sliver * (0.4 + 0.6 * progress);

    // Last-chance bin: strong discount to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0 * (1.0 - progress);
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (next_item_size as f64 / 100.0) * (0.5 + 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins when mean residual is large
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64) * (1.0 - progress);

    // New-bin candidate: make it attractive only when progress is low or fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = 1.0 - (item_size as f64 / bin_capacity as f64);
        score += 10.0 * progress - 5.0 * poor_fit * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
