            let dead_ratio = dead as f64 / post_residual.max(1) as f64;
            if dead > 0 {
                score += 22.0 * dead_ratio * (0.35 + 0.65 * progress);
            }
            // Pair-exact fill.
            if post_residual >= item_size + next_item_size {
                let after_pair = post_residual - item_size - next_item_size;
                if after_pair == 0 {
                    score -= 20.0 * remaining;
                } else if after_pair < item_size.min(next_item_size) {
                    score += 8.0 * (after_pair as f64 / cap) * remaining;
                }
            }
        } else {
            // Residual too small for the next item: penalize proportionally.
            score += 45.0 * (post / cap) + 35.0 * (1.0 - tightness);
            if post < item_size as f64 {
                score += 22.0 * (1.0 - post / cap) * (0.4 + 0.6 * progress);
            }
            if fitting_bins_count > 2 {
                score += 7.0 * (fitting_bins_count.min(6) as f64 - 2.0);
            }
        }
    }

    // Dead-space penalty for tiny unusable residuals.
    if post_residual < 10 && post_residual > 0 {
        score += 35.0 * (10.0 - post_residual as f64);
    }

    if bin_residual != bin_capacity {
        // Existing-bin branch.
        score -= 100.0 * progress;
        score -= 70.0 * tightness * tightness * progress;

        if fitting_bins_count == 1 {
            score -= 70.0;
        } else if fitting_bins_count > 1 {
            score += 3.5 * (fitting_bins_count as f64 - 1.0);
        }

        // Prefer bins with below-average residual (consolidate fullness).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 10.0 * dev;

        let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
        score += 45.0 * fit_gap;

        if bin_residual == item_size {
            score -= 30.0 * (0.5 + progress);
        }

        if post_residual > 0 && post_residual < item_size.min(next_item_size).max(1) {
            score += 30.0 * (1.0 - post / cap) * (0.3 + 0.7 * progress);
        }
        if post_residual >= next_item_size {
            let near = (post_residual - next_item_size) as f64;
            if near <= 3.0 {
                score -= 14.0 * (3.0 - near) * remaining;
            } else if near <= 8.0 {
                score -= 4.0 * (8.0 - near) * remaining;
            }
        }
        // High fill ratio bonus: near-exact fills are excellent.
        if bin_residual > 0 {
            let fill = item_size as f64 / bin_residual as f64;
            if fill > 0.85 && progress > 0.3 {
                score -= 24.0 * (fill - 0.85) * 5.0 * remaining;
            }
            if fill > 0.95 {
                score -= 18.0 * (fill - 0.95) * 20.0;
            }
        }
        if post_residual > 0 && post_residual < 6 && progress > 0.6 {
            score += 9.0 * progress;
        }
        if post_residual > 0 && post_residual >= next_item_size && post_residual <= next_item_size + item_size {
            score -= 6.0 * remaining;
        }
    } else {
        // NEW-BIN CANDIDATE branch.
        let crowding = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 240.0 * progress + 0.55 * mean_residual + 180.0 * crowding;
        score -= 150.0 * remaining * (1.0 - crowding);

        if next_item_size as f64 > 0.6 * cap {
            score -= 40.0;
        }
        if fitting_bins_count <= 1 {
            score -= 28.0 * remaining;
        }
        if fitting_bins_count == 0 {
            score -= 55.0;
        }
        let item_frac = item_size as f64 / cap;
        if item_frac > 0.6 && progress < 0.4 {
            score -= 22.0 * item_frac * remaining;
        }
        if item_frac < 0.25 && progress > 0.5 {
            score += 16.0 * (0.25 - item_frac) * 4.0 * progress;
        }
        // Fresh-bin leftover hosting the next item makes opening cheap.
        if bin_capacity - item_size == next_item_size {
            score -= 55.0 * remaining;
        }
        if post_residual >= 2 * next_item_size && post_residual % next_item_size.max(1) == 0 {
            score -= 22.0 * remaining;
        }
        if post_residual > 0 && post_residual < next_item_size {
            score += 22.0 * remaining;
        }
        // Saturation guard: when fleet mean residual is tiny, opening fresh
        // preserves usable space rather than forcing bad fits.
        if mean_residual / cap < 0.08 && fitting_bins_count > 0 && progress > 0.5 {
            score -= 28.0 * remaining;
        }
        // Preserve lookahead space when fleet can't host the next item.
        if next_item_size > 0
            && mean_residual > 0.0
            && (mean_residual / next_item_size as f64) < 0.5
            && fitting_bins_count > 0
            && progress > 0.4 {
            score -= 15.0 * remaining * (1.0 - mean_residual / next_item_size as f64);
        }
        if mean_residual / cap > 0.5 && progress > 0.6 {
            score += 32.0;
        }
        if item_frac > 0.5 && mean_residual / cap < 0.3 {
            score -= 18.0 * item_frac * remaining;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    let progress = step_index as f64 / total_items.max(1) as f64;
