    if post_residual >= 80 {
        score -= 20.0 * remaining;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 55.0;
    }
    if post_residual >= 10 && post_residual < 20 && post_residual % 10 != 0 {
        score += 25.0;
    }

    // Quarter/half capacity flexibility buckets.
    let quarter = (bin_capacity / 4) as f64;
    let half = (bin_capacity / 2) as f64;
    if post > half {
        score -= 15.0;
    } else if post < quarter && post_residual > 0 {
        score += 18.0;
    }

    // Lookahead pairing with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 950.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let chain = 235.0 * (1.0 - slack / cap);
            if slack < 14.0 {
                score -= chain - 90.0 - 5.0 * (14.0 - slack);
