        // sliver that no plausible upcoming item (<= cap/2) can use, tax it
        // progressively so near-full bins with unusable tails lose priority
        // to bins whose leftover stays usable.
        if post_residual > 0 && post_residual < item_size.min(next_item_size).max(1) {
