            score -= 28.0 * (0.5 + progress);
            if progress > 0.5 {
                score -= 23.0 * progress;
            }
        }

        if post_residual > 0 && post_residual < next_item_size {
            score += 24.0 * (1.0 - post / cap) * remaining;
        }
        if post_residual > 0 && post_residual < item_size.min(next_item_size).max(1) {
            score += 30.0 * (1.0 - post / cap) * (0.3 + 0.7 * progress);
            score += 16.0 * progress * progress;
        }
        if post_residual >= next_item_size
            && (post_residual % next_item_size.max(1)) == 0
            && post_residual != next_item_size {
            score -= 18.0 * remaining;
        }
        let post_dev = (post - mean_residual) / cap;
        score += 8.0 * post_dev * remaining;
        if fitting_bins_count <= 2 && post_residual > 0 {
            score -= 13.0 * tightness * remaining;
        }
        if post_residual >= next_item_size {
            let near = (post_residual - next_item_size) as f64;
            if near <= 3.0 {
                score -= 15.0 * (3.0 - near) * remaining;
            } else if near <= 8.0 {
                score -= 5.0 * (8.0 - near) * remaining;
            }
        }
        if bin_residual > 0 {
            let consume = item_size as f64 / bin_residual as f64;
            score -= 13.0 * consume * (0.4 + 0.6 * progress);
        }
        if post_residual > 0
            && post_residual as f64 > 0.18 * cap
            && post_residual < next_item_size.max(item_size)
            && open_bins_count > 2 {
            score += 11.0 * (open_bins_count.min(8) as f64 - 2.0) * remaining;
        }
        if progress > 0.65 {
            let pd = ((post - mean_residual) / cap).abs();
            score += 7.0 * pd * remaining;
        }
        if post_residual > 0 && post_residual % 10 == 0 && progress > 0.35 {
            score -= 7.0 * remaining;
        }
        // MUTATION: sharper near-exact fill gradient, active earlier.
        if bin_residual > 0 {
            let fill = item_size as f64 / bin_residual as f64;
            if fill > 0.8 && progress > 0.35 {
                score -= 28.0 * (fill - 0.8) * 5.0 * remaining;
            }
            if fill > 0.95 {
                score -= 22.0 * (fill - 0.95) * 20.0;
            }
        }
        // MUTATION: exact-fill bonus regardless of progress.
        if bin_residual == item_size && post_residual == 0 {
            score -= 65.0;
        }
        // MUTATION: harmonic leftover reward (from parent, retimed).
        if post_residual % 10 == 0 && post_residual > 0 {
            score -= 10.0 * remaining;
        }
        if post_residual > 0 && post_residual < 10 {
            score += 45.0 * (1.0 - post / 10.0) * remaining;
        }
    } else {
        // NEW-BIN CANDIDATE branch.
        let crowding = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 262.0 * progress + 0.55 * mean_residual + 192.0 * crowding;
        score -= 160.0 * remaining * (1.0 - crowding);

        if next_item_size as f64 > 0.6 * cap {
            score -= 45.0;
        }
        if fitting_bins_count > 1 && next_item_size as f64 > mean_residual.max(0.0) {
            score -= 20.0 * remaining;
        }
        if fitting_bins_count <= 1 {
            score -= 28.0 * remaining;
        }
        score += 0.18 * open_bins_count as f64 * (mean_residual / cap);
        score += (cap - item_size as f64) * 0.05 * progress;

        if post_residual == next_item_size {
            score -= 55.0 * remaining;
        }
        if progress > 0.55 {
            let waste = (cap - item_size as f64) / cap;
            score += 38.0 * waste * progress;
        }
        let item_frac = item_size as f64 / cap;
        if item_frac > 0.6 && progress < 0.4 {
            score -= 22.0 * item_frac * remaining;
        }
        if item_frac > 0.5 && progress > 0.35 && progress < 0.75 {
            score -= 15.0 * item_frac * remaining;
        }
        if item_frac < 0.25 && progress > 0.5 {
            score += 17.0 * (0.25 - item_frac) * 4.0 * progress;
        }
        if item_frac < 0.2 && progress > 0.4 {
            score += 28.0 * (0.2 - item_frac) * progress;
        }
        if fitting_bins_count == 0 {
            score -= 52.0;
        }
        if post_residual >= 2 * next_item_size
            && (post_residual % next_item_size.max(1)) == 0 {
            score -= 23.0 * remaining;
        }
        if fitting_bins_count > 0 && post_residual > next_item_size {
            score += 13.0 * remaining;
        }
        if post_residual > 0 && post_residual < next_item_size {
            score += 22.0 * remaining;
        }
        if item_frac > 0.5 && mean_residual / cap < 0.3 {
            score -= 18.0 * item_frac * remaining;
        }
        if bin_capacity - item_size == next_item_size {
            score -= 42.0 * remaining;
        }
        if post_residual > 0
            && post_residual < next_item_size
            && mean_residual / cap < 0.25
            && fitting_bins_count > 0 {
            score += 28.0 * remaining;
        }
        if next_item_size as f64 > 0.5 * cap
            && post_residual >= next_item_size
            && fitting_bins_count > 0 {
            score -= 24.0 * remaining;
        }
        // MUTATION: fleet saturation guard — don't force bad fits into
        // nearly exhausted bins.
        if mean_residual / cap < 0.08 && fitting_bins_count > 0 && progress > 0.5 {
            score -= 32.0 * remaining * (0.08 - mean_residual / cap) * 12.5;
        }
        // MUTATION: fresh-bin salvage — leftover hosting next item cheapens
        // opening even mid-stream.
        if bin_capacity - item_size == next_item_size && progress > 0.35 {
            score -= 15.0 * remaining;
        }
        // MUTATION: dead-space ratio guard — preserve usable space for the
        // lookahead when fleet residual is small relative to next item.
        if next_item_size > 0
            && mean_residual > 0.0
            && (mean_residual / next_item_size as f64) < 0.5
            && fitting_bins_count > 0
            && progress > 0.4 {
            score -= 17.0 * remaining * (1.0 - mean_residual / next_item_size as f64);
        }
        // MUTATION: late-stream fresh bins waste more; escalate penalty.
        if progress > 0.75 {
            score += 20.0 * (progress - 0.75) * 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let remaining = 1.0 - progress;
    let tightness = 1.0 - post / cap;

    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead pairing with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 950.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let chain = 235.0 * (1.0 - slack / cap);
            if slack < 14.0 {
                score -= chain - 90.0 - 5.0 * (14.0 - slack);
            } else {
                score -= chain;
            }
            if post_residual >= 2 * next_item_size {
                score -= 34.0 * remaining;
            }
            if post_residual == 2 * next_item_size {
                score -= 55.0 * remaining;
            }
            if post_residual >= 3 * next_item_size && next_item_size <= bin_capacity / 4 {
                score -= 22.0 * remaining;
            }
            if next_item_size > 1 && post_residual % next_item_size == 0 {
