                // reusable-pair gradient: leftover that can still host the
                // smaller of the two items is worth keeping.
                if after_pair >= item_size.min(next_item_size) {
                    score -= 9.0 * remaining * (1.0 - after_pair as f64 / cap);
                }
            }
            if post_residual > next_item_size && post_residual < next_item_size + 5 {
                score += 7.0 * remaining;
            }
            // MUTATION: dead-space entropy guard — residual left after the
            // next item that is neither zero nor reusable by the current
            // item is pure waste; scale penalty with stream progress.
            if dead > 0 && dead != item_size && dead < item_size {
                score += 22.0 * (dead as f64 / cap) * (0.5 + 0.5 * progress);
            }
