pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let remaining = 1.0 - progress;
    let tightness = 1.0 - post / cap;

    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead pairing with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 950.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let chain = 235.0 * (1.0 - slack / cap);
            if slack < 14.0 {
                score -= chain - 90.0 - 5.0 * (14.0 - slack);
            } else {
                score -= chain;
            }
            if post_residual >= 2 * next_item_size {
                score -= 34.0 * remaining;
            }
            if post_residual == 2 * next_item_size {
                score -= 55.0 * remaining;
            }
            if post_residual >= 3 * next_item_size && next_item_size <= bin_capacity / 4 {
                score -= 22.0 * remaining;
            }
            if next_item_size > 1 && post_residual % next_item_size == 0 {
                score -= 15.0 * remaining;
            }
            if slack as u32 == item_size {
                score -= 40.0;
            }
            if post_residual >= 2 * item_size {
                score -= 12.0 * remaining;
            }
            if slack > 0.0 {
                score -= 18.0 * (slack / cap) * remaining;
            }
            let dead = slack as u32;
            if dead > 0 && dead < item_size.min(next_item_size) {
                score += 185.0 * (dead as f64 / cap) * (0.4 + 0.6 * progress);
            }
            if dead >= 1 && dead <= 6 {
                score -= 12.0 * remaining;
            }
            if post_residual == 3 * next_item_size {
                score -= 30.0 * remaining;
            }
            let copies = dead / next_item_size.max(1);
            if copies >= 2 {
                score -= 9.0 * (copies.min(4) as f64) * remaining;
