            // Residual blocked relative to next item: penalize hard.
            let excess = (post - mean_residual).max(0.0);
            score += 60.0 + 0.78 * excess + 30.0 * (post / cap);
            score += 52.0 * (post / cap) * progress;
            if post < 8.0 && progress > 0.45 {
                score += 14.0;
            }
            if post > next_item_size as f64 * 1.5 && progress < 0.5 {
                score -= 10.0;
            }
            if post < item_size as f64 {
                score += 26.0 * (1.0 - post / cap) * (0.4 + 0.6 * progress);
            }
            if post < item_size as f64 && post < next_item_size as f64 {
                score += 25.0 * (1.0 - post / cap);
            }
            let dead = (post - next_item_size as f64).max(0.0);
            score += 90.0 * dead / cap * remaining;
            if fitting_bins_count > 2 {
                score += 8.0 * (fitting_bins_count.min(6) as f64 - 2.0);
            }
            let usable_frac = post / cap;
            if usable_frac > 0.45 {
                score -= 20.0 * (usable_frac - 0.45) * remaining;
            }
            if item_size > 0 && post_residual >= item_size {
                let rep = post_residual / item_size;
                if rep >= 2 {
                    score -= 7.0 * (rep.min(4) as f64) * remaining;
                }
            }
            if post_residual >= next_item_size {
                let hyp = (post_residual - next_item_size) as f64;
                score -= 12.0 * (1.0 - hyp / cap) * remaining;
            }
            if fitting_bins_count == 1 {
                score -= 45.0 + 20.0 * (post / cap);
            }
            // homogeneity pressure: prefer leftover matching fleet mean.
            if fitting_bins_count > 1 {
                let dev = ((post - mean_residual) / cap).abs();
                score += 10.0 * dev * remaining;
            }
        }
    }

    if bin_residual != bin_capacity {
        score -= 118.0 * progress;
        score -= 88.0 * tightness * tightness * progress;

        if fitting_bins_count == 1 {
            score -= 78.0;
        } else if fitting_bins_count > 1 {
            score += 3.8 * (fitting_bins_count as f64 - 1.0);
        }

        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 12.0 * dev;

        let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
        score += 55.0 * fit_gap;

        if bin_residual == item_size {
            score -= 30.0 * (0.5 + progress);
            if progress > 0.5 {
                score -= 25.0 * progress;
            }
        }

        if post_residual > 0 && post_residual < next_item_size {
            score += 26.0 * (1.0 - post / cap) * remaining;
        }
        if post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
            score += 18.0 * remaining;
        }
        if post_residual > 0 && post_residual < item_size.min(next_item_size).max(1) {
            score += 34.0 * (1.0 - post / cap) * (0.3 + 0.7 * progress);
            score += 18.0 * progress * progress;
        }
        if post_residual >= next_item_size
            && (post_residual % next_item_size.max(1)) == 0
            && post_residual != next_item_size {
            score -= 20.0 * remaining;
        }
        let post_dev = (post - mean_residual) / cap;
        score += 9.0 * post_dev * remaining;
        if post_residual > 0 && post_residual < 6 && progress > 0.6 {
            score += 10.0 * progress;
        }
        if fitting_bins_count <= 2 && post_residual > 0 {
            score -= 14.0 * tightness * remaining;
        }
        if post_residual >= next_item_size {
            let near = (post_residual - next_item_size) as f64;
            if near <= 3.0 {
                score -= 16.0 * (3.0 - near) * remaining;
            } else if near <= 8.0 {
                score -= 5.0 * (8.0 - near) * remaining;
            }
        }
        if post_residual > 0 && bin_residual > item_size {
            let leftover = (bin_residual - item_size) as f64;
            score += 20.0 * (leftover / cap) * (0.5 + progress);
        }
        if post_residual > 0 && post_residual < next_item_size && open_bins_count > 3 {
            score += 10.0 * (open_bins_count.min(10) as f64 - 3.0) * (1.0 - post / cap) * remaining;
        }
        if bin_residual > 0 {
            let consume = item_size as f64 / bin_residual as f64;
            score -= 14.0 * consume * (0.4 + 0.6 * progress);
        }
        if post_residual > 0
            && post_residual as f64 > 0.18 * cap
            && post_residual < next_item_size.max(item_size)
            && open_bins_count > 2 {
            score += 12.0 * (open_bins_count.min(8) as f64 - 2.0) * remaining;
        }
        if progress > 0.8 && post_residual == next_item_size.max(1) {
            score -= 20.0 * remaining;
        }
        if progress > 0.65 {
            let pd = ((post - mean_residual) / cap).abs();
            score += 8.0 * pd * remaining;
        }
        if post_residual > 0 && post_residual < item_size.min(next_item_size).max(1) {
            score += 14.0 * (1.0 - post / cap) * open_bins_count.min(6) as f64;
        }
        if progress > 0.6 && post_residual >= 1 && post_residual <= 4 {
            score -= 10.0 * (5.0 - post as f64) * remaining;
        }
        if post_residual > 0 && post_residual % 10 == 0 && progress > 0.35 {
            score -= 8.0 * remaining;
        }
        if progress > 0.7 && post_residual > 0 {
            score += 6.0 * (post_residual as f64 / cap) * (progress - 0.7) * 10.0;
        }
        if post_residual > 0 && post_residual >= next_item_size && post_residual <= next_item_size + item_size {
            score -= 6.0 * remaining;
        }
        // Sharper near-exact fill gradient late in the stream.
        if bin_residual > 0 {
            let fill = item_size as f64 / bin_residual as f64;
            if fill > 0.8 && progress > 0.4 {
                score -= 26.0 * (fill - 0.8) * 5.0 * remaining;
            }
            if fill > 0.95 {
                score -= 20.0 * (fill - 0.95) * 20.0;
            }
        }
        // Exact-fill bonus — a bin whose residual equals the item
        // wastes nothing; reward regardless of progress.
        if bin_residual == item_size && post_residual == 0 {
            score -= 60.0;
        }
        // MUTATION: dead-space ratio refinement — when the leftover after
        // this placement is a small unusable fragment relative to the next
        // item, penalize proportionally to how much stream remains.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let frag = post_residual as f64 / next_item_size as f64;
            score += 20.0 * (1.0 - frag) * remaining * (0.5 + 0.5 * progress);
        }
        // MUTATION: near-miss salvage — a leftover just below the next item
        // can still host the current item class later; soften the penalty
        // when the fragment is at least half the next item.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let frag = post_residual as f64 / next_item_size as f64;
            if frag >= 0.5 {
                score -= 10.0 * remaining;
            }
        }
    } else {
        // NEW-BIN CANDIDATE branch.
        let crowding = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 268.0 * progress + 0.58 * mean_residual + 198.0 * crowding;
        score -= 168.0 * remaining * (1.0 - crowding);

        if next_item_size as f64 > 0.6 * cap {
            score -= 48.0;
        }
        if fitting_bins_count > 1 && next_item_size as f64 > mean_residual.max(0.0) {
            score -= 22.0 * remaining;
        }
        if fitting_bins_count <= 1 {
            score -= 30.0 * remaining;
        }
        score += 0.20 * open_bins_count as f64 * (mean_residual / cap);
        score += (cap - item_size as f64) * 0.05 * progress;

        if post_residual == next_item_size {
            score -= 60.0 * remaining;
        }
        if mean_residual / cap > 0.5 && progress > 0.6 {
            score += 35.0;
        }
        if progress > 0.55 {
            let waste = (cap - item_size as f64) / cap;
            score += 40.0 * waste * progress;
        }
        let item_frac = item_size as f64 / cap;
        if item_frac > 0.6 && progress < 0.4 {
            score -= 24.0 * item_frac * remaining;
        }
        if item_frac > 0.5 && progress > 0.35 && progress < 0.75 {
            score -= 16.0 * item_frac * remaining;
        }
        if item_frac < 0.25 && progress > 0.5 {
            score += 18.0 * (0.25 - item_frac) * 4.0 * progress;
        }
        if item_frac < 0.2 && progress > 0.4 {
            score += 30.0 * (0.2 - item_frac) * progress;
        }
        if fitting_bins_count == 0 {
            score -= 55.0;
        }
        if post_residual >= 2 * next_item_size
            && (post_residual % next_item_size.max(1)) == 0 {
            score -= 25.0 * remaining;
        }
        if fitting_bins_count > 0 && post_residual > next_item_size {
            score += 14.0 * remaining;
        }
        if post_residual > 0 && post_residual < next_item_size {
            score += 24.0 * remaining;
        }
        if post_residual > 0
            && post_residual < item_size.min(next_item_size).max(1)
            && progress > 0.3 {
            score += 20.0 * (0.3 + 0.7 * progress);
        }
        if item_frac > 0.5 && mean_residual / cap < 0.3 {
            score -= 20.0 * item_frac * remaining;
        }
        if bin_capacity - item_size == next_item_size {
            score -= 45.0 * remaining;
        }
        if post_residual > 0
            && post_residual < next_item_size
            && mean_residual / cap < 0.25
            && fitting_bins_count > 0 {
            score += 30.0 * remaining;
        }
        if item_frac > 0.4
            && next_item_size > 0
            && post_residual >= 2 * next_item_size
            && post_residual % next_item_size == 0 {
            score -= 18.0 * remaining;
        }
        if post_residual as f64 > mean_residual + 0.3 * cap && fitting_bins_count > 0 {
            score -= 12.0 * remaining;
        }
        if post_residual > 0
            && post_residual < next_item_size
            && (post_residual as f64) > 0.5 * cap
            && progress > 0.5 {
            score += 26.0 * remaining;
        }
        if next_item_size > 0 && post_residual >= 3 * next_item_size {
            score -= 14.0 * remaining;
        }
        if post_residual % 10 == 0 && post_residual > 0 {
            score -= 12.0 * remaining;
        }
        if mean_residual / cap > 0.35 && item_frac < 0.5 && progress > 0.3 {
            score += 18.0 * (mean_residual / cap) * remaining;
        }
        if item_frac < 0.35 && fitting_bins_count > 0 && progress < 0.6 {
            score += 22.0 * (1.0 - item_frac) * (fitting_bins_count.min(5) as f64) * remaining;
        }
        if next_item_size as f64 > 0.5 * cap
            && post_residual >= next_item_size
            && fitting_bins_count > 0 {
            score -= 26.0 * remaining;
        }
        if bin_capacity - item_size == next_item_size && progress > 0.5 {
            score -= 20.0 * remaining;
        }
        // Fleet saturation guard — when open bins are nearly
        // exhausted (tiny mean residual), don't force bad fits into them.
        if mean_residual / cap < 0.08 && fitting_bins_count > 0 && progress > 0.5 {
            score -= 30.0 * remaining * (0.08 - mean_residual / cap) * 12.5;
        }
        // Fresh-bin salvage — a brand-new bin's leftover exactly
        // hosting the next item makes opening cheap even mid-stream.
        if bin_capacity - item_size == next_item_size && progress > 0.35 {
            score -= 14.0 * remaining;
        }
        // Dead-space ratio guard — when the fleet's mean residual
        // is small relative to the next item, opening a fresh bin preserves
        // usable space for the lookahead instead of scattering it.
        if next_item_size > 0
            && mean_residual > 0.0
            && (mean_residual / next_item_size as f64) < 0.5
            && fitting_bins_count > 0
            && progress > 0.4 {
            score -= 16.0 * remaining * (1.0 - mean_residual / next_item_size as f64);
        }
        // MUTATION: fresh-bin dead-space budget — opening a new bin leaves
        // (cap - item) of fresh space; when that leftover can host the next
        // item with slack below a tight threshold, opening is cheap even
        // early in the stream.
        if next_item_size > 0 {
            let fresh_left = bin_capacity - item_size;
            if fresh_left >= next_item_size {
                let fresh_dead = fresh_left - next_item_size;
                let frac = fresh_dead as f64 / cap;
                if frac < 0.10 {
                    score -= 24.0 * (0.10 - frac) * 10.0 * (0.4 + 0.6 * remaining);
                }
            } else {
                // fresh bin cannot host next item at all: penalize more
                // when the deficit is small (near-miss waste).
                let miss = (next_item_size - fresh_left) as f64;
                if miss <= 10.0 {
                    score += 18.0 * (1.0 - miss / 10.0) * remaining;
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
