            // item is the primary waste source; penalize it proportionally
            // to how close it is to the minimum item size.
            if dead > 0 && dead < item_size.min(next_item_size) {
                let wedge = 1.0 - (dead as f64) / (item_size.min(next_item_size) as f64);
