            }
            if dead as f64 > 0.25 * cap && progress > 0.5 && open_bins_count > 2 {
                score += 16.0 * (dead / cap) * progress;
            }
            if post_residual >= item_size + next_item_size {
                let after_pair = post_residual - item_size - next_item_size;
                if after_pair == 0 {
                    score -= 22.0 * remaining;
                } else if after_pair <= 4 {
                    score -= 10.0 * remaining;
                } else if after_pair < item_size.min(next_item_size) {
                    score += 8.0 * (after_pair as f64 / cap) * remaining;
                }
                // reusable-pair gradient: leftover that can still host the
                // smaller of the two items is worth keeping.
                if after_pair >= item_size.min(next_item_size) {
                    score -= 9.0 * remaining * (1.0 - after_pair as f64 / cap);
                }
            }
            if post_residual > next_item_size && post_residual < next_item_size + 5 {
                score += 7.0 * remaining;
            }
            // dead-space ratio refinement — penalize placements whose
            // leftover exceeds the next item by a wide unusable margin,
            // scaled by stream progress (tightened threshold).
            if dead as f64 > next_item_size as f64 * 1.35 && progress > 0.3 {
                score += 15.0 * ((dead as f64 / next_item_size as f64) - 1.35).min(2.0) * progress;
            }
            // MUTATION: usable-remainder continuity — leftover that can host
            // the item after next (i.e. a 2-deep lookahead) is valuable;
            // reward proportional to how deep the chain reaches.
            let chain_depth = dead / next_item_size.max(1);
            if chain_depth >= 1 && next_item_size as f64 <= 0.35 * cap {
                score -= 7.0 * (chain_depth.min(3) as f64) * remaining * (1.0 - dead as f64 / cap);
            }
            // penalize leftovers that are too small to host anything likely
            // (below the minimum plausible item size band).
            if dead > 0 && dead < 4 && progress < 0.5 {
                score += 6.0 * (4 - dead) as f64;
            }
        } else if post_residual > 0 {
            // Residual blocked relative to next item: penalize hard.
            let excess = (post - mean_residual).max(0.0);
            score += 60.0 + 0.78 * excess + 30.0 * (post / cap);
            score += 52.0 * (post / cap) * progress;
            if post < 8.0 && progress > 0.45 {
                score += 14.0;
            }
            if post > next_item_size as f64 * 1.5 && progress < 0.5 {
                score -= 10.0;
            }
            if post < item_size as f64 {
                score += 26.0 * (1.0 - post / cap) * (0.4 + 0.6 * progress);
            }
            if post < item_size as f64 && post < next_item_size as f64 {
                score += 25.0 * (1.0 - post / cap);
            }
            let dead = (post - next_item_size as f64).max(0.0);
            score += 90.0 * dead / cap * remaining;
            if fitting_bins_count > 2 {
                score += 8.0 * (fitting_bins_count.min(6) as f64 - 2.0);
            }
            let usable_frac = post / cap;
            if usable_frac > 0.45 {
                score -= 20.0 * (usable_frac - 0.45) * remaining;
            }
            if item_size > 0 && post_residual >= item_size {
                let rep = post_residual / item_size;
                if rep >= 2 {
                    score -= 7.0 * (rep.min(4) as f64) * remaining;
                }
            }
            if post_residual >= next_item_size {
                let hyp = (post_residual - next_item_size) as f64;
                score -= 12.0 * (1.0 - hyp / cap) * remaining;
            }
            if fitting_bins_count == 1 {
                score -= 45.0 + 20.0 * (post / cap);
            }
            // homogeneity pressure: prefer leftover matching fleet mean.
            if fitting_bins_count > 1 {
                let dev = ((post - mean_residual) / cap).abs();
                score += 10.0 * dev * remaining;
            }
            // MUTATION: when this blocked bin's residual is close to the
            // next item (nearly usable), soften the penalty so a single
            // off-by-few leftover isn't treated like true dead space.
            let gap_to_next = (next_item_size as f64 - post).max(0.0);
            if gap_to_next > 0.0 && gap_to_next <= 6.0 {
                score -= 9.0 * (6.0 - gap_to_next) * remaining;
            }
        }
    }

    if bin_residual != bin_capacity {
        score -= 118.0 * progress;
        score -= 88.0 * tightness * tightness * progress;

        if fitting_bins_count == 1 {
            score -= 78.0;
        } else if fitting_bins_count > 1 {
            score += 3.8 * (fitting_bins_count as f64 - 1.0);
        }

        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 12.0 * dev;

        let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
        score += 55.0 * fit_gap;

        if bin_residual == item_size {
            score -= 30.0 * (0.5 + progress);
            if progress > 0.5 {
                score -= 25.0 * progress;
            }
        }

        if post_residual > 0 && post_residual < next_item_size {
            score += 26.0 * (1.0 - post / cap) * remaining;
        }
        if post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
            score += 18.0 * remaining;
        }
        if post_residual > 0 && post_residual < item_size.min(next_item_size).max(1) {
            score += 34.0 * (1.0 - post / cap) * (0.3 + 0.7 * progress);
            score += 18.0 * progress * progress;
        }
        if post_residual >= next_item_size
            && (post_residual % next_item_size.max(1)) == 0
            && post_residual != next_item_size {
            score -= 20.0 * remaining;
        }
        let post_dev = (post - mean_residual) / cap;
        score += 9.0 * post_dev * remaining;
        if post_residual > 0 && post_residual < 6 && progress > 0.6 {
            score += 10.0 * progress;
        }
        if fitting_bins_count <= 2 && post_residual > 0 {
            score -= 14.0 * tightness * remaining;
        }
        if post_residual >= next_item_size {
            let near = (post_residual - next_item_size) as f64;
            if near <= 3.0 {
                score -= 16.0 * (3.0 - near) * remaining;
            } else if near <= 8.0 {
                score -= 5.0 * (8.0 - near) * remaining;
            }
        }
        if post_residual > 0 && bin_residual > item_size {
            let leftover = (bin_residual - item_size) as f64;
            score += 20.0 * (leftover / cap) * (0.5 + progress);
        }
        if post_residual > 0 && post_residual < next_item_size && open_bins_count > 3 {
            score += 10.0 * (open_bins_count.min(10) as f64 - 3.0) * (1.0 - post / cap) * remaining;
        }
        if bin_residual > 0 {
            let consume = item_size as f64 / bin_residual as f64;
            score -= 14.0 * consume * (0.4 + 0.6 * progress);
        }
        if post_residual > 0
            && post_residual as f64 > 0.18 * cap
            && post_residual < next_item_size.max(item_size)
            && open_bins_count > 2 {
            score += 12.0 * (open_bins_count.min(8) as f64 - 2.0) * remaining;
        }
        if progress > 0.8 && post_residual == next_item_size.max(1) {
            score -= 20.0 * remaining;
        }
        if progress > 0.65 {
            let pd = ((post - mean_residual) / cap).abs();
            score += 8.0 * pd * remaining;
        }
        if post_residual > 0 && post_residual < item_size.min(next_item_size).max(1) {
            score += 14.0 * (1.0 - post / cap) * open_bins_count.min(6) as f64;
        }
        if progress > 0.6 && post_residual >= 1 && post_residual <= 4 {
            score -= 10.0 * (5.0 - post as f64) * remaining;
        }
        if post_residual > 0 && post_residual % 10 == 0 && progress > 0.35 {
            score -= 8.0 * remaining;
        }
        if progress > 0.7 && post_residual > 0 {
            score += 6.0 * (post_residual as f64 / cap) * (progress - 0.7) * 10.0;
        }
        if post_residual > 0 && post_residual >= next_item_size && post_residual <= next_item_size + item_size {
            score -= 6.0 * remaining;
        }
        // sharper near-exact fill gradient late in the stream.
        if bin_residual > 0 {
            let fill = item_size as f64 / bin_residual as f64;
            if fill > 0.8 && progress > 0.4 {
                score -= 26.0 * (fill - 0.8) * 5.0 * remaining;
            }
            // super-saturating exact-fill bonus — a bin whose residual
            // exactly equals the item wastes nothing.
            if fill > 0.95 {
                score -= 20.0 * (fill - 0.95) * 20.0;
            }
            // MUTATION: mid-band fill smoothing — reward fills just below
            // the sharp gradient so near-perfect fits in the 0.65–0.8 band
            // are preferred over scattered mid-size placements.
            if fill > 0.65 && fill <= 0.8 && progress > 0.45 {
                score -= 14.0 * (fill - 0.65) * remaining;
            }
        }
        if bin_residual == item_size && post_residual == 0 {
            score -= 60.0;
        }
        // MUTATION: variance-aware homogenization — bins whose post-fit
        // residual lands close to the fleet mean keep future items
        // placeable; reward closeness to mean residual.
        if post_residual > 0 {
            let pd2 = ((post - mean_residual) / cap).abs();
            if pd2 < 0.1 {
                score -= 12.0 * (0.1 - pd2) * 10.0 * remaining;
            }
        }
    } else {
        // NEW-BIN CANDIDATE branch.
        let crowding = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 268.0 * progress + 0.58 * mean_residual + 198.0 * crowding;
        score -= 168.0 * remaining * (1.0 - crowding);

        if next_item_size as f64 > 0.6 * cap {
            score -= 48.0;
        }
        if fitting_bins_count > 1 && next_item_size as f64 > mean_residual.max(0.0) {
            score -= 22.0 * remaining;
        }
        if fitting_bins_count <= 1 {
            score -= 30.0 * remaining;
        }
        score += 0.20 * open_bins_count as f64 * (mean_residual / cap);
        score += (cap - item_size as f64) * 0.05 * progress;

        if post_residual == next_item_size {
            score -= 60.0 * remaining;
        }
        if mean_residual / cap > 0.5 && progress > 0.6 {
            score += 35.0;
        }
        if progress > 0.55 {
            let waste = (cap - item_size as f64) / cap;
            score += 40.0 * waste * progress;
        }
        let item_frac = item_size as f64 / cap;
        if item_frac > 0.6 && progress < 0.4 {
            score -= 24.0 * item_frac * remaining;
        }
        if item_frac > 0.5 && progress > 0.35 && progress < 0.75 {
            score -= 16.0 * item_frac * remaining;
        }
        if item_frac < 0.25 && progress > 0.5 {
            score += 18.0 * (0.25 - item_frac) * 4.0 * progress;
        }
        if item_frac < 0.2 && progress > 0.4 {
            score += 30.0 * (0.2 - item_frac) * progress;
        }
        if fitting_bins_count == 0 {
            score -= 55.0;
        }
        if post_residual >= 2 * next_item_size
            && (post_residual % next_item_size.max(1)) == 0 {
            score -= 25.0 * remaining;
        }
        if fitting_bins_count > 0 && post_residual > next_item_size {
            score += 14.0 * remaining;
        }
        if post_residual > 0 && post_residual < next_item_size {
            score += 24.0 * remaining;
        }
        if post_residual > 0
            && post_residual < item_size.min(next_item_size).max(1)
            && progress > 0.3 {
            score += 20.0 * (0.3 + 0.7 * progress);
        }
        if item_frac > 0.5 && mean_residual / cap < 0.3 {
            score -= 20.0 * item_frac * remaining;
        }
        if bin_capacity - item_size == next_item_size {
            score -= 45.0 * remaining;
        }
        if post_residual > 0
            && post_residual < next_item_size
            && mean_residual / cap < 0.25
            && fitting_bins_count > 0 {
            score += 30.0 * remaining;
        }
        if item_frac > 0.4
            && next_item_size > 0
            && post_residual >= 2 * next_item_size
            && post_residual % next_item_size == 0 {
            score -= 18.0 * remaining;
        }
        if post_residual as f64 > mean_residual + 0.3 * cap && fitting_bins_count > 0 {
            score -= 12.0 * remaining;
        }
        if post_residual > 0
            && post_residual < next_item_size
            && (post_residual as f64) > 0.5 * cap
            && progress > 0.5 {
            score += 26.0 * remaining;
        }
        if next_item_size > 0 && post_residual >= 3 * next_item_size {
            score -= 14.0 * remaining;
        }
        if post_residual % 10 == 0 && post_residual > 0 {
            score -= 12.0 * remaining;
        }
        if mean_residual / cap > 0.35 && item_frac < 0.5 && progress > 0.3 {
            score += 18.0 * (mean_residual / cap) * remaining;
        }
        if item_frac < 0.35 && fitting_bins_count > 0 && progress < 0.6 {
            score += 22.0 * (1.0 - item_frac) * (fitting_bins_count.min(5) as f64) * remaining;
        }
        if next_item_size as f64 > 0.5 * cap
            && post_residual >= next_item_size
            && fitting_bins_count > 0 {
            score -= 26.0 * remaining;
        }
        // fleet saturation guard — when open bins are nearly exhausted
        // (tiny mean residual), don't force bad fits into them.
        if mean_residual / cap < 0.08 && fitting_bins_count > 0 && progress > 0.5 {
            score -= 30.0 * remaining * (0.08 - mean_residual / cap) * 12.5;
        }
        // fresh-bin salvage — a brand-new bin's leftover exactly hosting
        // the next item makes opening cheap even mid-stream.
        if bin_capacity - item_size == next_item_size && progress > 0.35 {
            score -= 14.0 * remaining;
        }
        // dead-space ratio guard — when the fleet's mean residual is small
        // relative to the next item, opening a fresh bin preserves usable
        // space for the lookahead instead of scattering it.
        if next_item_size > 0
            && mean_residual > 0.0
            && (mean_residual / next_item_size as f64) < 0.5
            && fitting_bins_count > 0
            && progress > 0.4 {
            score -= 16.0 * remaining * (1.0 - mean_residual / next_item_size as f64);
        }
        // early-stream reserve — with a large lookahead item and few
        // fitting bins, opening fresh space early avoids fragmenting
        // residual capacity later.
        if next_item_size as f64 > 0.45 * cap && fitting_bins_count <= 2 && progress < 0.4 {
            score -= 12.0 * remaining * (0.45 - item_frac).max(0.0) * 4.0;
        }
        // MUTATION: exact-pair salvage — when the fresh bin's leftover
        // exactly fits the next item AND the remaining-after-next residual
        // matches a plausible small item, opening is nearly free.
        if next_item_size > 0
            && bin_capacity - item_size == next_item_size
            && (bin_capacity - item_size - next_item_size) == 0 {
            score -= 22.0 * remaining;
        }
        // MUTATION: fragmentation forecast — penalize opening a new bin
        // late in the stream when the fleet still holds a large aggregate
        // residual that could absorb several more items.
        let fleet_agg = mean_residual * open_bins_count as f64;
        if progress > 0.6 && fleet_agg > 2.5 * (item_size as f64) {
            score += 10.0 * ((fleet_agg / (2.5 * item_size as f64)) - 1.0).min(2.0) * remaining;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let remaining = 1.0 - progress;
    let tightness = 1.0 - post / cap;

    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead pairing with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 950.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let chain = 235.0 * (1.0 - slack / cap);
            if slack < 14.0 {
                score -= chain - 90.0 - 5.0 * (14.0 - slack);
            } else {
                score -= chain;
            }
            if post_residual >= 2 * next_item_size {
                score -= 34.0 * remaining;
            }
            if post_residual == 2 * next_item_size {
                score -= 55.0 * remaining;
            }
            if post_residual >= 3 * next_item_size && next_item_size <= bin_capacity / 4 {
                score -= 22.0 * remaining;
            }
            if next_item_size > 1 && post_residual % next_item_size == 0 {
                score -= 15.0 * remaining;
            }
            if slack as u32 == item_size {
                score -= 40.0;
            }
            if post_residual >= 2 * item_size {
                score -= 12.0 * remaining;
            }
            if slack > 0.0 {
                score -= 18.0 * (slack / cap) * remaining;
            }
            let dead = slack as u32;
            if dead > 0 && dead < item_size.min(next_item_size) {
                score += 185.0 * (dead as f64 / cap) * (0.4 + 0.6 * progress);
            }
            if dead >= 1 && dead <= 6 {
                score -= 12.0 * remaining;
            }
            if post_residual == 3 * next_item_size {
                score -= 30.0 * remaining;
            }
            let copies = dead / next_item_size.max(1);
            if copies >= 2 {
                score -= 9.0 * (copies.min(4) as f64) * remaining;
            }
            if dead > 0 && dead < next_item_size && dead <= item_size {
                score -= 14.0 * remaining;
            }
            if post_residual >= 2 * next_item_size {
                let after2 = post_residual - 2 * next_item_size;
                if after2 == 0 {
                    score -= 48.0 * remaining;
                } else if after2 < next_item_size {
                    score -= 10.0 * remaining;
                    score += 20.0 * (after2 as f64 / cap);
                }
            }
            let dead_ratio = dead as f64 / post_residual.max(1) as f64;
            if dead > 0 {
                score += 26.0 * dead_ratio * (0.35 + 0.65 * progress);
            }
            if dead >= item_size.min(next_item_size).max(1) && dead as f64 <= cap * 0.35 {
                score -= 10.0 * (1.0 - dead as f64 / (cap * 0.35)) * remaining;
            }
            if dead > 0 && dead_ratio < 0.25 && progress > 0.5 {
                score -= 9.0 * (1.0 - dead_ratio) * remaining;
            }
            if dead >= 1 && dead <= 3 {
                score -= (4.0 - dead as f64) * 8.0 * (0.5 + 0.5 * remaining);
            }
            if dead > next_item_size.max(6) && dead < 3 * next_item_size && dead < item_size {
                score += 12.0 * (dead as f64 / cap) * progress;
            }
            if dead as f64 > 0.25 * cap && progress > 0.5 && open_bins_count > 2 {
                score += 16.0 * (dead / cap) * progress;
            }
            if post_residual >= item_size + next_item_size {
                let after_pair = post_residual - item_size - next_item_size;
                if after_pair == 0 {
                    score -= 22.0 * remaining;
                } else if after_pair <= 4 {
                    score -= 10.0 * remaining;
                } else if after_pair < item_size.min(next_item_size) {
                    score += 8.0 * (after_pair as f64 / cap) * remaining;
                }
                // reusable-pair gradient: leftover that can still host the
                // smaller of the two items is worth keeping.
                if after_pair >= item_size.min(next_item_size) {
                    score -= 9.0 * remaining * (1.0 - after_pair as f64 / cap);
                }
            }
            if post_residual > next_item_size && post_residual < next_item_size + 5 {
                score += 7.0 * remaining;
            }
            // dead-space ratio refinement — penalize placements
            // whose leftover exceeds the next item by a wide unusable
            // margin, scaled by stream progress.
            if dead as f64 > next_item_size as f64 * 1.5 && progress > 0.35 {
                score += 12.0 * ((dead as f64 / next_item_size as f64) - 1.5).min(2.0) * progress;
            }
            // MUTATION: dead-space ratio gradient — reward placements whose
            // leftover fraction is small relative to the residual, steering
            // selection toward bins where the next item dominates the fill.
            if dead > 0 && dead_ratio < 0.4 {
                score -= 7.0 * (0.4 - dead_ratio) * (1.0 - progress) * (1.0 + tightness);
            }
            // MUTATION: tight-fill coupling — when the placement consumes
            // most of the residual, the dead space is structurally small;
            // amplify the chain reward for high utilization late-stream.
            let util = item_size as f64 / bin_residual.max(1) as f64;
            if util > 0.7 && dead as f64 <= 0.2 * cap {
                score -= 10.0 * (util - 0.7) * (1.0 + progress);
            }
        } else if post_residual > 0 {
            // Residual blocked relative to next item: penalize hard.
            let excess = (post - mean_residual).max(0.0);
            score += 60.0 + 0.78 * excess + 30.0 * (post / cap);
            score += 52.0 * (post / cap) * progress;
            if post < 8.0 && progress > 0.45 {
                score += 14.0;
            }
            if post > next_item_size as f64 * 1.5 && progress < 0.5 {
                score -= 10.0;
            }
            if post < item_size as f64 {
                score += 26.0 * (1.0 - post / cap) * (0.4 + 0.6 * progress);
            }
            if post < item_size as f64 && post < next_item_size as f64 {
                score += 25.0 * (1.0 - post / cap);
            }
            let dead = (post - next_item_size as f64).max(0.0);
            score += 90.0 * dead / cap * remaining;
            if fitting_bins_count > 2 {
                score += 8.0 * (fitting_bins_count.min(6) as f64 - 2.0);
            }
            let usable_frac = post / cap;
            if usable_frac > 0.45 {
                score -= 20.0 * (usable_frac - 0.45) * remaining;
            }
            if item_size > 0 && post_residual >= item_size {
                let rep = post_residual / item_size;
                if rep >= 2 {
                    score -= 7.0 * (rep.min(4) as f64) * remaining;
                }
            }
            if post_residual >= next_item_size {
                let hyp = (post_residual - next_item_size) as f64;
                score -= 12.0 * (1.0 - hyp / cap) * remaining;
            }
            if fitting_bins_count == 1 {
                score -= 45.0 + 20.0 * (post / cap);
            }
            // homogeneity pressure: prefer leftover matching fleet mean.
            if fitting_bins_count > 1 {
                let dev = ((post - mean_residual) / cap).abs();
                score += 10.0 * dev * remaining;
            }
            // MUTATION: stranded-residual guard — a blocked bin whose
            // residual is just below the next item is a fragment trap;
            // penalize proportionally to how close it is to being usable.
            if post < next_item_size as f64 && post >= next_item_size as f64 * 0.6 {
                score += 18.0 * (1.0 - post / (next_item_size as f64)) * remaining;
            }
        }
    }

    if bin_residual != bin_capacity {
        score -= 118.0 * progress;
        score -= 88.0 * tightness * tightness * progress;

        if fitting_bins_count == 1 {
            score -= 78.0;
        } else if fitting_bins_count > 1 {
            score += 3.8 * (fitting_bins_count as f64 - 1.0);
        }

        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 12.0 * dev;

        let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
        score += 55.0 * fit_gap;

        if bin_residual == item_size {
            score -= 30.0 * (0.5 + progress);
            if progress > 0.5 {
                score -= 25.0 * progress;
            }
        }

        if post_residual > 0 && post_residual < next_item_size {
            score += 26.0 * (1.0 - post / cap) * remaining;
        }
        if post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
            score += 18.0 * remaining;
        }
        if post_residual > 0 && post_residual < item_size.min(next_item_size).max(1) {
            score += 34.0 * (1.0 - post / cap) * (0.3 + 0.7 * progress);
            score += 18.0 * progress * progress;
        }
        if post_residual >= next_item_size
            && (post_residual % next_item_size.max(1)) == 0
            && post_residual != next_item_size {
            score -= 20.0 * remaining;
        }
        let post_dev = (post - mean_residual) / cap;
        score += 9.0 * post_dev * remaining;
        if post_residual > 0 && post_residual < 6 && progress > 0.6 {
            score += 10.0 * progress;
        }
        if fitting_bins_count <= 2 && post_residual > 0 {
            score -= 14.0 * tightness * remaining;
        }
        if post_residual >= next_item_size {
            let near = (post_residual - next_item_size) as f64;
            if near <= 3.0 {
                score -= 16.0 * (3.0 - near) * remaining;
            } else if near <= 8.0 {
                score -= 5.0 * (8.0 - near) * remaining;
            }
        }
        if post_residual > 0 && bin_residual > item_size {
            let leftover = (bin_residual - item_size) as f64;
            score += 20.0 * (leftover / cap) * (0.5 + progress);
        }
        if post_residual > 0 && post_residual < next_item_size && open_bins_count > 3 {
            score += 10.0 * (open_bins_count.min(10) as f64 - 3.0) * (1.0 - post / cap) * remaining;
        }
        if bin_residual > 0 {
            let consume = item_size as f64 / bin_residual as f64;
            score -= 14.0 * consume * (0.4 + 0.6 * progress);
        }
        if post_residual > 0
            && post_residual as f64 > 0.18 * cap
            && post_residual < next_item_size.max(item_size)
            && open_bins_count > 2 {
            score += 12.0 * (open_bins_count.min(8) as f64 - 2.0) * remaining;
        }
        if progress > 0.8 && post_residual == next_item_size.max(1) {
            score -= 20.0 * remaining;
        }
        if progress > 0.65 {
            let pd = ((post - mean_residual) / cap).abs();
            score += 8.0 * pd * remaining;
        }
        if post_residual > 0 && post_residual < item_size.min(next_item_size).max(1) {
            score += 14.0 * (1.0 - post / cap) * open_bins_count.min(6) as f64;
        }
        if progress > 0.6 && post_residual >= 1 && post_residual <= 4 {
            score -= 10.0 * (5.0 - post as f64) * remaining;
        }
        if post_residual > 0 && post_residual % 10 == 0 && progress > 0.35 {
            score -= 8.0 * remaining;
        }
        if progress > 0.7 && post_residual > 0 {
            score += 6.0 * (post_residual as f64 / cap) * (progress - 0.7) * 10.0;
        }
        if post_residual > 0 && post_residual >= next_item_size && post_residual <= next_item_size + item_size {
            score -= 6.0 * remaining;
        }
        // sharper near-exact fill gradient late in the stream.
        if bin_residual > 0 {
            let fill = item_size as f64 / bin_residual as f64;
            if fill > 0.8 && progress > 0.4 {
                score -= 26.0 * (fill - 0.8) * 5.0 * remaining;
            }
            // super-saturating exact-fill bonus — a bin whose residual
            // exactly equals the item wastes nothing.
            if fill > 0.95 {
                score -= 20.0 * (fill - 0.95) * 20.0;
            }
        }
        if bin_residual == item_size && post_residual == 0 {
            score -= 60.0;
        }
        // MUTATION: fragment-avoidance bias — penalize bins whose post-fit
        // residual falls just under the next item's size when alternative
        // fitting bins exist; such near-miss leftovers are dead weight.
        if post_residual > 0
            && post_residual < next_item_size
            && next_item_size > 0
            && fitting_bins_count > 1
            && post_residual as f64 >= 0.5 * next_item_size as f64 {
            score += 15.0 * remaining * (post_residual as f64 / next_item_size as f64);
        }
    } else {
        // NEW-BIN CANDIDATE branch.
        let crowding = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 268.0 * progress + 0.58 * mean_residual + 198.0 * crowding;
        score -= 168.0 * remaining * (1.0 - crowding);

        if next_item_size as f64 > 0.6 * cap {
            score -= 48.0;
        }
        if fitting_bins_count > 1 && next_item_size as f64 > mean_residual.max(0.0) {
            score -= 22.0 * remaining;
        }
        if fitting_bins_count <= 1 {
            score -= 30.0 * remaining;
        }
        score += 0.20 * open_bins_count as f64 * (mean_residual / cap);
        score += (cap - item_size as f64) * 0.05 * progress;

        if post_residual == next_item_size {
            score -= 60.0 * remaining;
        }
        if mean_residual / cap > 0.5 && progress > 0.6 {
            score += 35.0;
        }
        if progress > 0.55 {
            let waste = (cap - item_size as f64) / cap;
            score += 40.0 * waste * progress;
        }
        let item_frac = item_size as f64 / cap;
        if item_frac > 0.6 && progress < 0.4 {
            score -= 24.0 * item_frac * remaining;
        }
        if item_frac > 0.5 && progress > 0.35 && progress < 0.75 {
            score -= 16.0 * item_frac * remaining;
        }
        if item_frac < 0.25 && progress > 0.5 {
            score += 18.0 * (0.25 - item_frac) * 4.0 * progress;
        }
        if item_frac < 0.2 && progress > 0.4 {
            score += 30.0 * (0.2 - item_frac) * progress;
        }
        if fitting_bins_count == 0 {
            score -= 55.0;
        }
        if post_residual >= 2 * next_item_size
            && (post_residual % next_item_size.max(1)) == 0 {
            score -= 25.0 * remaining;
        }
        if fitting_bins_count > 0 && post_residual > next_item_size {
            score += 14.0 * remaining;
        }
        if post_residual > 0 && post_residual < next_item_size {
            score += 24.0 * remaining;
        }
        if post_residual > 0
            && post_residual < item_size.min(next_item_size).max(1)
            && progress > 0.3 {
            score += 20.0 * (0.3 + 0.7 * progress);
        }
        if item_frac > 0.5 && mean_residual / cap < 0.3 {
            score -= 20.0 * item_frac * remaining;
        }
        if bin_capacity - item_size == next_item_size {
            score -= 45.0 * remaining;
        }
        if post_residual > 0
            && post_residual < next_item_size
            && mean_residual / cap < 0.25
            && fitting_bins_count > 0 {
            score += 30.0 * remaining;
        }
        if item_frac > 0.4
            && next_item_size > 0
            && post_residual >= 2 * next_item_size
            && post_residual % next_item_size == 0 {
            score -= 18.0 * remaining;
        }
        if post_residual as f64 > mean_residual + 0.3 * cap && fitting_bins_count > 0 {
            score -= 12.0 * remaining;
        }
        if post_residual > 0
            && post_residual < next_item_size
            && (post_residual as f64) > 0.5 * cap
            && progress > 0.5 {
            score += 26.0 * remaining;
        }
        if next_item_size > 0 && post_residual >= 3 * next_item_size {
            score -= 14.0 * remaining;
        }
        if post_residual % 10 == 0 && post_residual > 0 {
            score -= 12.0 * remaining;
        }
        if mean_residual / cap > 0.35 && item_frac < 0.5 && progress > 0.3 {
            score += 18.0 * (mean_residual / cap) * remaining;
        }
        if item_frac < 0.35 && fitting_bins_count > 0 && progress < 0.6 {
            score += 22.0 * (1.0 - item_frac) * (fitting_bins_count.min(5) as f64) * remaining;
        }
        if next_item_size as f64 > 0.5 * cap
            && post_residual >= next_item_size
            && fitting_bins_count > 0 {
            score -= 26.0 * remaining;
        }
        // fleet saturation guard — when open bins are nearly exhausted
        // (tiny mean residual), don't force bad fits into them.
        if mean_residual / cap < 0.08 && fitting_bins_count > 0 && progress > 0.5 {
            score -= 30.0 * remaining * (0.08 - mean_residual / cap) * 12.5;
        }
        // fresh-bin salvage — a brand-new bin's leftover exactly hosting
        // the next item makes opening cheap even mid-stream.
        if bin_capacity - item_size == next_item_size && progress > 0.35 {
            score -= 14.0 * remaining;
        }
        // dead-space ratio guard — when the fleet's mean residual is small
        // relative to the next item, opening a fresh bin preserves usable
        // space for the lookahead instead of scattering it.
        if next_item_size > 0
            && mean_residual > 0.0
            && (mean_residual / next_item_size as f64) < 0.5
            && fitting_bins_count > 0
            && progress > 0.4 {
            score -= 16.0 * remaining * (1.0 - mean_residual / next_item_size as f64);
        }
        // early-stream reserve — with a large lookahead item and
        // few fitting bins, opening fresh space early avoids fragmenting
        // residual capacity later.
        if next_item_size as f64 > 0.45 * cap && fitting_bins_count <= 2 && progress < 0.4 {
            score -= 12.0 * remaining * (0.45 - item_frac).max(0.0) * 4.0;
        }
        // MUTATION: fresh-bin utilization gradient — when the new bin's
        // post residual would host the next item exactly or nearly so,
        // reward opening it more strongly; this reduces dead space left
        // behind by mediocre fits into nearly-full open bins.
        if next_item_size > 0 {
            let fresh_post = (bin_capacity - item_size) as f64;
            let gap = (fresh_post - next_item_size as f64).abs();
            if gap <= 4.0 {
                score -= (26.0 - 4.0 * gap) * remaining;
            } else if fresh_post >= next_item_size as f64 {
                let d = fresh_post - next_item_size as f64;
                if d < next_item_size as f64 {
                    score -= 8.0 * (1.0 - d / next_item_size as f64) * remaining;
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let remaining = 1.0 - progress;
    let tightness = 1.0 - post / cap;

    // Perfect fill: zero waste is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead pairing with the next item.
    if next_item_size > 0 && bin_residual != bin_capacity {
        if post_residual == next_item_size {
            score -= 950.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 180.0 * (1.0 - slack / cap);
            if slack < 12.0 {
                score -= 70.0 - 5.0 * slack;
            }
            if post_residual >= 2 * next_item_size {
                score -= 30.0 * remaining;
            }
            if post_residual == 2 * next_item_size {
                score -= 55.0 * remaining;
            }
            if post_residual >= 3 * next_item_size && next_item_size <= bin_capacity / 4 {
                score -= 20.0 * remaining;
            }
            if slack as u32 == item_size {
                score -= 40.0;
            }
            // dead-space penalty relative to the next item
            if slack > 0.0 && slack < item_size.min(next_item_size) as f64 {
                score += 150.0 * (slack / cap) * (0.4 + 0.6 * progress);
            }
            if slack as u32 >= 1 && slack <= 6.0 {
                score -= 12.0 * remaining;
            }
            if slack as f64 > next_item_size as f64 * 1.5 && progress > 0.35 {
                score += 12.0 * ((slack / next_item_size as f64) - 1.5).min(2.0) * progress;
            }
        } else if post_residual > 0 {
            // blocked residual: penalize hard, scaled by wasted fraction
            score += 60.0 + 0.7 * (post - mean_residual).max(0.0) + 30.0 * (post / cap);
            score += 50.0 * (post / cap) * progress;
            if post < item_size as f64 {
                score += 26.0 * (1.0 - post / cap) * (0.4 + 0.6 * progress);
            }
            if fitting_bins_count == 1 {
                score -= 60.0 + 20.0 * (post / cap);
            } else if fitting_bins_count > 1 {
                score += 4.0 * (fitting_bins_count.min(6) as f64 - 1.0);
            }
        }
    }

    if bin_residual != bin_capacity {
        // Existing-bin branch: reward tightness and progress.
        score -= 110.0 * progress;
        score -= 80.0 * tightness * tightness * progress;

        if fitting_bins_count == 1 {
            score -= 70.0;
        } else if fitting_bins_count > 1 {
            score += 3.8 * (fitting_bins_count as f64 - 1.0);
        }

        // Prefer emptier bins (consume residual capacity first).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 12.0 * dev;

        let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
        score += 55.0 * fit_gap;

        if bin_residual == item_size {
            score -= 30.0 * (0.5 + progress);
        }
        if bin_residual == item_size && post_residual == 0 {
            score -= 60.0;
        }

        // Exact/near-exact fill gradient.
        if bin_residual > 0 {
            let fill = item_size as f64 / bin_residual as f64;
            score -= 14.0 * fill * (0.4 + 0.6 * progress);
            if fill > 0.8 && progress > 0.4 {
                score -= 26.0 * (fill - 0.8) * 5.0 * remaining;
            }
            if fill > 0.95 {
                score -= 20.0 * (fill - 0.95) * 20.0;
            }
        }

        if post_residual > 0 && post_residual < next_item_size.max(1) {
            score += 26.0 * (1.0 - post / cap) * remaining;
        }
        if post_residual > 0 && post_residual < item_size.min(next_item_size).max(1) {
            score += 34.0 * (1.0 - post / cap) * (0.3 + 0.7 * progress);
        }
        if post_residual >= next_item_size {
            let near = (post_residual - next_item_size) as f64;
            if near <= 3.0 {
                score -= 16.0 * (3.0 - near) * remaining;
            } else if near <= 8.0 {
                score -= 5.0 * (8.0 - near) * remaining;
            }
        }
        if post_residual > 0 && post_residual < 6 && progress > 0.6 {
            score += 10.0 * progress;
        }
        if fitting_bins_count <= 2 && post_residual > 0 {
            score -= 14.0 * tightness * remaining;
        }
        let post_dev = (post - mean_residual) / cap;
        score += 9.0 * post_dev * remaining;
    } else {
        // NEW-BIN CANDIDATE branch.
        let crowding = 1.0 / (fitting_bins_count.max(1) as f64);
        let item_frac = item_size as f64 / cap;
        score += 268.0 * progress + 0.55 * mean_residual + 190.0 * crowding;
        score -= 168.0 * remaining * (1.0 - crowding);

        if next_item_size as f64 > 0.6 * cap {
            score -= 48.0;
        }
        if fitting_bins_count <= 1 {
            score -= 30.0 * remaining;
        }
        if fitting_bins_count == 0 {
            score -= 55.0;
        }
        score += 0.20 * open_bins_count as f64 * (mean_residual / cap);
        score += (cap - item_size as f64) * 0.05 * progress;

        // Fresh-bin salvage: leftover exactly hosting next item makes opening cheap.
        if post_residual == next_item_size {
            score -= 60.0 * remaining;
        }
        if bin_capacity - item_size == next_item_size {
            score -= 45.0 * remaining;
        }
        if item_frac > 0.6 && progress < 0.4 {
            score -= 24.0 * item_frac * remaining;
        }
        if item_frac < 0.25 && progress > 0.5 {
            score += 18.0 * (0.25 - item_frac) * 4.0 * progress;
        }
        if post_residual >= 2 * next_item_size && post_residual % next_item_size.max(1) == 0 {
            score -= 25.0 * remaining;
        }
        if post_residual > 0 && post_residual < next_item_size {
            score += 24.0 * remaining;
        }
        // Fleet saturation guard: tiny mean residual means existing bins are
        // nearly exhausted; opening fresh space preserves usable capacity.
        if mean_residual / cap < 0.08 && fitting_bins_count > 0 && progress > 0.5 {
            score -= 30.0 * remaining * (0.08 - mean_residual / cap) * 12.5;
        }
        if next_item_size > 0
            && mean_residual > 0.0
            && (mean_residual / next_item_size as f64) < 0.5
            && fitting_bins_count > 0
            && progress > 0.4 {
            score -= 16.0 * remaining * (1.0 - mean_residual / next_item_size as f64);
        }
        // Early-stream reserve for large lookahead items.
        if next_item_size as f64 > 0.45 * cap && fitting_bins_count <= 2 && progress < 0.4 {
            score -= 12.0 * remaining * (0.45 - item_frac).max(0.0) * 4.0;
        }
        if mean_residual / cap > 0.5 && progress > 0.6 {
            score += 35.0;
        }
        if item_frac < 0.35 && fitting_bins_count > 0 && progress < 0.6 {
            score += 22.0 * (1.0 - item_frac) * (fitting_bins_count.min(5) as f64) * remaining;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let remaining = 1.0 - progress;
    let tightness = 1.0 - post / cap;

    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead pairing with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 950.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let chain = 235.0 * (1.0 - slack / cap);
            if slack < 14.0 {
                score -= chain - 90.0 - 5.0 * (14.0 - slack);
