        if item_frac < 0.3 && mean_residual / cap > item_frac * 2.0 && fitting_bins_count > 1 {
            score += 25.0 * (1.0 - item_frac / (mean_residual / cap).max(0.01)) * remaining;
        }
    }

    score
}

