            }
            if post_residual > next_item_size && post_residual < next_item_size + 5 {
                score += 7.0 * remaining;
            }
            if dead as f64 > next_item_size as f64 * 1.5 && progress > 0.35 {
                score += 12.0 * ((dead as f64 / next_item_size as f64) - 1.5).min(2.0) * progress;
            }
            // MUTATION: fit-quality coupling — reward placements whose
            // dead space is small AND whose residual still exceeds the
            // next item by a reusable margin; scale by fleet pressure.
            let fleet_pressure = (fitting_bins_count.min(8) as f64) / 8.0;
            if dead > 0 && dead as f64 <= next_item_size as f64 * 0.5 {
                score -= 16.0 * (1.0 - dead as f64 / (next_item_size as f64 * 0.5))
                    * fleet_pressure * remaining;
            }
            // MUTATION: tightness-lookahead product — bins that become
