        }
        if progress > 0.6 && post_residual >= 1 && post_residual <= 4 {
            score -= 9.5 * (5.0 - post as f64) * remaining;
        }
        if post_residual > 0 && post_residual % 10 == 0 && progress > 0.35 {
            score -= 7.5 * remaining;
        }
        if progress > 0.7 && post_residual > 0 {
            score += 5.5 * (post_residual as f64 / cap) * (progress - 0.7) * 10.0;
        }
        if post_residual > 0 && post_residual >= next_item_size && post_residual <= next_item_size + item_size {
            score -= 5.5 * remaining;
        }
        // Sharper near-exact fill gradient late in the stream.
        if bin_residual > 0 {
            let fill = item_size as f64 / bin_residual as f64;
            if fill > 0.8 && progress > 0.4 {
                score -= 25.0 * (fill - 0.8) * 5.0 * remaining;
            }
            if fill > 0.95 {
                score -= 19.0 * (fill - 0.95) * 20.0;
            }
        }
        if bin_residual == item_size && post_residual == 0 {
            score -= 58.0;
        }
        // MUTATION: harmonic-residue bonus — post_residual that is a
        // multiple of 10 is more likely reusable by future items.
        if post_residual > 0 && post_residual % 10 == 0 && post_residual >= 20 {
            score -= 6.0 * remaining;
        }
        // MUTATION: fragmentation guard — small odd leftovers late in the
        // stream are almost always dead space.
        if post_residual > 0 && post_residual < 12 && post_residual % 2 == 1 && progress > 0.55 {
