        }
        if next_item_size as f64 > 0.5 * cap
            && post_residual >= next_item_size
            && fitting_bins_count > 0 {
            score -= 25.0 * remaining;
        }
        if mean_residual / cap < 0.08 && fitting_bins_count > 0 && progress > 0.5 {
            score -= 29.0 * remaining * (0.08 - mean_residual / cap) * 12.5;
        }
        if bin_capacity - item_size == next_item_size && progress > 0.35 {
            score -= 13.5 * remaining;
        }
        if next_item_size > 0
            && mean_residual > 0.0
            && (mean_residual / next_item_size as f64) < 0.5
            && fitting_bins_count > 0
            && progress > 0.4 {
            score -= 15.5 * remaining * (1.0 - mean_residual / next_item_size as f64);
        }
        if next_item_size as f64 > 0.45 * cap && fitting_bins_count <= 2 && progress < 0.4 {
            score -= 11.5 * remaining * (0.45 - item_frac).max(0.0) * 4.0;
        }
        // MUTATION: fresh-bin harmonic check — opening a bin whose leftover
        // is a multiple of 10 is slightly cheaper (reusable dead space).
        if post_residual % 10 == 0 && post_residual >= 20 {
            score -= 8.0 * remaining;
        }
        // MUTATION: late-stream squeeze — near the end, opening a new bin
        // for small items is wasteful; make it costlier.
        if item_frac < 0.3 && progress > 0.75 {
            score += 20.0 * (0.3 - item_frac) * 4.0 * (progress - 0.75) * 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

