        if bin_residual > 0 {
            let fill = item_size as f64 / bin_residual as f64;
            if fill > 0.8 && progress > 0.4 {
                score -= 26.0 * (fill - 0.8) * 5.0 * remaining;
            }
            // super-saturating exact-fill bonus.
            if fill > 0.95 {
                score -= 20.0 * (fill - 0.95) * 20.0;
            }
        }
        if bin_residual == item_size && post_residual == 0 {
            score -= 60.0;
        }
        // MUTATION: tight-fit tiebreak — when several bins fit, prefer the
        // one whose post-residual is closest to the fleet mean residual so
        // remaining capacity stays uniform and reusable.
        if fitting_bins_count > 2 && post_residual > 0 {
            let pd2 = ((post - mean_residual) / cap).abs();
            if pd2 < 0.1 {
