        if progress > 0.55 {
            let waste = (cap - item_size as f64) / cap;
            score += 40.0 * waste * progress;
        }
        let item_frac = item_size as f64 / cap;
        if item_frac > 0.6 && progress < 0.4 {
            score -= 24.0 * item_frac * remaining;
        }
        if item_frac > 0.5 && progress > 0.35 && progress < 0.75 {
            score -= 16.0 * item_frac * remaining;
        }
        if item_frac < 0.25 && progress > 0.5 {
            score += 18.0 * (0.25 - item_frac) * 4.0 * progress;
        }
        if item_frac < 0.2 && progress > 0.4 {
            score += 30.0 * (0.2 - item_frac) * progress;
        }
        if fitting_bins_count == 0 {
            score -= 55.0;
        }
        if post_residual >= 2 * next_item_size
            && (post_residual % next_item_size.max(1)) == 0 {
            score -= 25.0 * remaining;
        }
        if fitting_bins_count > 0 && post_residual > next_item_size {
            score += 14.0 * remaining;
        }
        if post_residual > 0 && post_residual < next_item_size {
            score += 24.0 * remaining;
        }
        if post_residual > 0
            && post_residual < item_size.min(next_item_size).max(1)
            && progress > 0.3 {
            score += 20.0 * (0.3 + 0.7 * progress);
        }
        if item_frac > 0.5 && mean_residual / cap < 0.3 {
            score -= 20.0 * item_frac * remaining;
        }
        if bin_capacity - item_size == next_item_size {
            score -= 45.0 * remaining;
        }
        if post_residual > 0
            && post_residual < next_item_size
            && mean_residual / cap < 0.25
            && fitting_bins_count > 0 {
            score += 30.0 * remaining;
        }
        if item_frac > 0.4
            && next_item_size > 0
            && post_residual >= 2 * next_item_size
            && post_residual % next_item_size == 0 {
            score -= 18.0 * remaining;
        }
        if post_residual as f64 > mean_residual + 0.3 * cap && fitting_bins_count > 0 {
            score -= 12.0 * remaining;
        }
        if post_residual > 0
            && post_residual < next_item_size
            && (post_residual as f64) > 0.5 * cap
            && progress > 0.5 {
            score += 26.0 * remaining;
        }
        if next_item_size > 0 && post_residual >= 3 * next_item_size {
            score -= 14.0 * remaining;
        }
        if post_residual % 10 == 0 && post_residual > 0 {
            score -= 12.0 * remaining;
        }
        if mean_residual / cap > 0.35 && item_frac < 0.5 && progress > 0.3 {
            score += 18.0 * (mean_residual / cap) * remaining;
        }
        if item_frac < 0.35 && fitting_bins_count > 0 && progress < 0.6 {
            score += 22.0 * (1.0 - item_frac) * (fitting_bins_count.min(5) as f64) * remaining;
        }
        if next_item_size as f64 > 0.5 * cap
            && post_residual >= next_item_size
            && fitting_bins_count > 0 {
            score -= 26.0 * remaining;
        }
        // fleet saturation guard — when open bins are nearly exhausted
        // (tiny mean residual), don't force bad fits into them.
        if mean_residual / cap < 0.08 && fitting_bins_count > 0 && progress > 0.5 {
            score -= 30.0 * remaining * (0.08 - mean_residual / cap) * 12.5;
        }
        // fresh-bin salvage — a brand-new bin's leftover exactly hosting
        // the next item makes opening cheap even mid-stream.
        if bin_capacity - item_size == next_item_size && progress > 0.35 {
            score -= 14.0 * remaining;
        }
        // dead-space ratio guard — when the fleet's mean residual is small
        // relative to the next item, opening a fresh bin preserves usable
        // space for the lookahead instead of scattering it.
        if next_item_size > 0
            && mean_residual > 0.0
            && (mean_residual / next_item_size as f64) < 0.5
            && fitting_bins_count > 0
            && progress > 0.4 {
            score -= 16.0 * remaining * (1.0 - mean_residual / next_item_size as f64);
        }
        // MUTATION: early-stream reserve — with a large lookahead item and
        // few fitting bins, opening fresh space early avoids fragmenting
        // residual capacity later.
        if next_item_size as f64 > 0.45 * cap && fitting_bins_count <= 2 && progress < 0.4 {
            score -= 12.0 * remaining * (0.45 - item_frac).max(0.0) * 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: leftovers in "large residue" classes are
    // more reusable. Class = post_residual / (capacity / 8) bucket, 0..7.
    let class_size = bin_capacity / 8;
    let residue_class = (post_residual / class_size) as f64;

    // Reward big leftover classes (more room for future items).
    score -= residue_class * 6.0;

    // Penalize tiny, awkward leftovers (dead space): class 0 or 1.
    if post_residual < class_size {
        score += 12.0;
    } else if post_residual < 2 * class_size {
        score += 5.0;
    }

    // Exact-fill is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits exactly in the post-residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Harmonic divisibility bonus: next item divides the leftover nicely.
            if post_residual % next_item_size == 0 {
                score -= 15.0;
            }
            score -= 8.0;
        } else {
            // Next item won't fit in leftover: penalize proportional to overflow gap.
            score += ((next_item_size - post_residual) as f64) * 0.5;
        }
    }

    // Last-chance bin: only one fitting bin; strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has high post_residual; only
    // prefer it when the current best fit would create heavy dead space.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 30.0;
        // But if the current item is large relative to capacity, a fresh bin
        // gives a clean harmonic partition; reduce penalty.
        if item_size * 2 >= bin_capacity {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 15.0;
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter bins first).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Many open bins: discourage spreading, favor filling existing ones.
    if open_bins_count > 4 {
        score += (open_bins_count as f64) * 0.2;
    }

    // Modulo-16 harmonic bonus on post_residual: leftovers that are multiples
    // of 16 align with common item sizes.
    if post_residual % 16 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let remaining = 1.0 - progress;
    let tightness = 1.0 - post / cap;

    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead pairing with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 950.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let chain = 235.0 * (1.0 - slack / cap);
            if slack < 14.0 {
                score -= chain - 90.0 - 5.0 * (14.0 - slack);
            } else {
                score -= chain;
            }
            if post_residual >= 2 * next_item_size {
                score -= 34.0 * remaining;
            }
            if post_residual == 2 * next_item_size {
                score -= 55.0 * remaining;
            }
            if post_residual >= 3 * next_item_size && next_item_size <= bin_capacity / 4 {
                score -= 22.0 * remaining;
